'use strict';
const $=s=>document.querySelector(s),app=$('#app'),dialog=$('#dialog');
const icons={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',task:'M9 5h11v15H4V5h2m2-2h8v4H8Zm0 10 2 2 4-4',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',calendar:'M8 2v4m8-4v4M3 10h18M4 4h16a1 1 0 0 1 1 1v15a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M15 3a4 4 0 0 1 0 8M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',leave:'M7 21h10M12 21V9M4 9a8 8 0 0 1 16 0c-3-2-5-2-8 0-3-2-5-2-8 0Z',meeting:'M16 8l6-4v16l-6-4M3 5h11a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2',document:'M14 2H5a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9Zm0 0v7h7M7 13h10M7 17h10',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Zm-4 10 3 3 5-6',chart:'M4 19h17M7 15V9m5 6V4m5 11v-4',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',menu:'M4 6h16M4 12h16M4 18h16',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',logout:'M9 4H4v16h5m6-15 6 7-6 7M8 12h13',lock:'M5 10h14v11H5Zm3 0V6a4 4 0 0 1 8 0v4',hash:'M5 9h15M4 15h15M11 3 7 21M17 3l-4 18',send:'m22 2-7 20-4-9-9-4Zm0 0L11 13',refresh:'M20 7v5h-5M4 17v-5h5M5 7a8 8 0 0 1 13-3l2 3M4 17l2 3a8 8 0 0 0 13-3',info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',copy:'M8 8h13v13H8ZM3 16V3h13',briefcase:'M9 6V3h6v3M3 6h18v15H3Zm0 7h18m-11-2v4h4v-4',heart:'m20 5 1 2v4c-1 4-9 10-9 10S4 15 3 11V7l1-2c3-4 7-2 8 1 1-3 5-5 8-1',folder:'M2 5h8l2 3h10v13H2Z'};
function icon(name){return `<svg class="svg" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.document}"/></svg>`;}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const human=v=>String(v||'').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
const roles={founder:'Founder',hr_lead:'HR Lead',hr_member:'HR Member',team_lead:'Team Lead',employee:'Team Member',finance_head:'Finance Head'};
const departments=['Company','Leadership','HR','Marketing','Finance','Strategy'];
const TZ='Asia/Kolkata';
function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:TZ,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());}
function date(v,full=false){if(!v)return '—';const d=new Date(/^\d{4}-\d{2}-\d{2}$/.test(v)?v+'T00:00:00+05:30':v);return Number.isNaN(d.getTime())?'—':new Intl.DateTimeFormat('en-IN',{timeZone:TZ,day:'numeric',month:'short',...(full?{year:'numeric'}:{})}).format(d);}
function datetime(v){if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime())?'—':new Intl.DateTimeFormat('en-IN',{timeZone:TZ,day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}).format(d);}
function time(v){if(!v)return '—';return new Intl.DateTimeFormat('en-IN',{timeZone:TZ,hour:'numeric',minute:'2-digit'}).format(new Date(v));}
function hours(s){return `${Math.floor(Math.max(0,s||0)/3600)}h ${Math.floor(Math.max(0,s||0)%3600/60)}m`;}
function safeURL(v){try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function initials(v){return String(v||'?').split(/\s+/).map(w=>w[0]).slice(0,2).join('').toUpperCase();}
let user=null,people=[],channels=[],notifications=[],unread=0,route='',pageToken=0,records={},calendarOffset=0,taskFilter='all',pendingLogin=false;
const isFounder=()=>user?.role==='founder',isHR=()=>['founder','hr_lead','hr_member'].includes(user?.role),isLead=()=>['founder','team_lead','hr_lead','finance_head'].includes(user?.role),canReport=()=>isHR()||isLead();

function manageableDepartments(){return isFounder()?departments:user.role==='hr_lead'?['Company','HR']:[user.department];}
function canManageDepartment(d){return isFounder()||(user.role==='hr_lead'&&['Company','HR'].includes(d))||(['team_lead','finance_head'].includes(user.role)&&user.department===d);}
function notificationLink(v){if(typeof v!=='string')return '';const r=v.replace(/^#?\/?(?:api\/)?/,'');if(r==='schedule'||r==='schedules')return '#attendance';return /^(home|guide|tasks|attendance|leave|calendar|people|meetings|documents|grievances|hr|reports|performance|exits|notifications|account)(?:$|[/?])/.test(r)?'#'+r.split(/[/?]/)[0]:r.startsWith('channel/')?'#'+r:'';}
function person(id){return people.find(p=>p.id===id);}
function nameOf(id){return person(id)?.name||'Team member';}
function avatar(p,cls=''){return `<span class="avatar ${cls}" aria-hidden="true">${esc(initials(typeof p==='string'?p:p?.name))}</span>`;}
function badge(status){const green=['working','approved','done','active','available','resolved'].includes(status),amber=['pending_lead','pending_hr','review','revision','on_leave','break','on_break'].includes(status),red=['overdue','rejected','suspended','urgent','unavailable'].includes(status);return `<span class="badge ${green?'green':amber?'amber':red?'red':''}"><span class="status-dot"></span>${esc(human(status||'offline'))}</span>`;}
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),5500);}
async function api(path,method='GET',body){const res=await fetch(path,{method,credentials:'same-origin',headers:body===undefined?{}:{'Content-Type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});let data;try{data=await res.json();}catch{throw new Error('The workspace could not respond. Please try again.');}if(!res.ok){if(res.status===401&&user){user=null;renderLogin();}throw new Error(data.error||'This action could not be completed.');}return data;}
const button=(text,action='',kind='',extra='')=>`<button class="btn ${kind}" ${action?`data-action="${action}"`:''} ${extra}>${esc(text)}</button>`;
const plusButton=(text,action)=>`<button class="btn primary" data-action="${action}">${icon('plus')}${esc(text)}</button>`;
function empty(title,description='',glyph='folder',action=''){return `<div class="empty"><div class="empty-icon">${icon(glyph)}</div><h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`;}
function pageHeading(title,subtitle,action='',eyebrow='TEAM WORKSPACE'){return `<header class="page-title"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${action}</header>`;}
function navLink(id,title,glyph,count=''){return `<a class="nav-link ${route===id?'active':''}" href="#${id}" ${route===id?'aria-current="page"':''}>${icon(glyph)}<span>${esc(title)}</span>${count?`<span class="count">${esc(count)}</span>`:''}</a>`;}
function renderLogin(){dialog.close();app.innerHTML=`<div class="auth"><section class="auth-story"><div class="brand"><img class="tel-logo" src="/tel-logo.webp" alt="TEL" width="183" height="96"><div><strong>TEL OS<span class="accent">.</span></strong><small>Ideas. Made real.</small></div></div><div class="auth-copy"><div class="eyebrow accent">YOUR TEAM'S OPERATING SYSTEM</div><h1>Ideas. Made real.<br>Work. Made simple.</h1><p>Your place to clock in, find your next task, and keep the team in sync.</p></div><div class="auth-foot">Tech for Easy Life &nbsp; / &nbsp; Built for the way your team works</div></section><main class="auth-form" id="main"><div class="login-card"><div class="eyebrow">WELCOME TO THE WORKSPACE</div><h2>Let's get you signed in.</h2><p class="muted">Use your individual TEL OS account.</p><form id="login-form"><div class="form-error" role="alert" tabindex="-1"></div>${field('Username','username','text',{autocomplete:'username',required:true,placeholder:'Your account username'})}${field('Password','password','password',{autocomplete:'current-password',required:true})}<button class="btn primary full" type="submit">Sign in ${icon('arrow')}</button></form><div class="hint">First time here? Your temporary password must be changed before you can access team records. Contact Humaira or Himan for account help.</div><div class="note">${icon('lock')}<span>Your work account is personal. Keep your password private.</span></div></div></main></div>`;$('#login-form').addEventListener('submit',async e=>{e.preventDefault();if(pendingLogin)return;pendingLogin=true;const f=e.currentTarget,b=f.querySelector('button');b.disabled=true;b.textContent='Signing in…';try{const data=await api('/api/auth/login','POST',formData(f));user=data.user;await boot();}catch(err){formError(f,err.message);b.disabled=false;b.innerHTML='Sign in '+icon('arrow');}finally{pendingLogin=false;}});}
function field(label,name,type='text',opts={}){const {required=false,value='',placeholder='',hint='',autocomplete='',min='',max='',step='',wide=false,rows=4}=opts;let input;if(type==='textarea')input=`<textarea id="f-${name}" name="${name}" rows="${rows}" ${required?'required':''} placeholder="${esc(placeholder)}">${esc(value)}</textarea>`;else if(type==='select')input=`<select id="f-${name}" name="${name}" ${required?'required':''} ${opts.multiple?'multiple':''}>${(opts.options||[]).map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`;}).join('')}</select>`;else input=`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${placeholder?`placeholder="${esc(placeholder)}"`:''} ${autocomplete?`autocomplete="${autocomplete}"`:''} ${min!==''?`min="${esc(min)}"`:''} ${max!==''?`max="${esc(max)}"`:''} ${step!==''?`step="${esc(step)}"`:''} ${opts.minlength?`minlength="${opts.minlength}"`:''} ${opts.maxlength?`maxlength="${opts.maxlength}"`:''}>`;return `<div class="field ${wide?'wide':''}"><label for="f-${name}">${esc(label)}${required?' <span aria-hidden="true">*</span>':''}</label>${input}${hint?`<small>${esc(hint)}</small>`:''}</div>`;}
function formData(f){return Object.fromEntries(new FormData(f));}
function formError(f,message){const el=f.querySelector('.form-error');if(el){el.textContent=message;el.focus();}else toast(message,true);}
function openDialog(title,content,{locked=false}={}){dialog.className=locked?'no-close':'';dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-content">${content}</div>`;if(!dialog.open)dialog.showModal();dialog.oncancel=e=>{if(locked)e.preventDefault();};return dialog;}
function modalForm(title,fields,onSubmit,{description='',submit='Save',locked=false,after}={}){openDialog(title,`${description?`<p class="dialog-subtitle">${esc(description)}</p>`:''}<form id="modal-form"><div class="form-error" role="alert" tabindex="-1"></div>${fields}<div class="form-actions">${locked?button('Sign out','logout'):button('Cancel','close-dialog')}<button class="btn primary" type="submit">${esc(submit)}</button></div></form>`,{locked});$('#modal-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('[type="submit"]');if(b.disabled)return;b.disabled=true;b.textContent='Saving…';try{const result=await onSubmit(formData(f),f);dialog.close();if(after)await after(result);else{toast('Saved successfully.');await refresh();}}catch(err){formError(f,err.message);b.disabled=false;b.textContent=submit;}});}
function peopleOptions(filter=()=>true,none=false){return [...(none?[['','No handover']]:[]),...people.filter(filter).map(p=>[p.id,`${p.name} · ${p.designation||roles[p.role]||p.department}`])];}
function shell(){
 const titleMap={home:'Home',guide:'Start here',tasks:'My tasks',attendance:'Attendance',leave:'Time off',calendar:'Team calendar',people:'People',meetings:'Meetings',documents:'Policies & documents',grievances:'HR desk & tickets',hr:'People admin',reports:'Team reports',performance:'Feedback',exits:'Leaving the team',notifications:'Notifications',account:'My account'};
 app.innerHTML=`<div class="workspace"><button class="mobile-overlay" data-action="toggle-menu" aria-label="Close navigation"></button><aside class="sidebar"><a class="brand" href="#home" aria-label="TEL OS home"><img class="tel-logo" src="/tel-logo.webp" alt="TEL" width="183" height="96"><div><strong>OS<span class="accent">.</span></strong><small>Team workspace</small></div></a><div class="workspace-name"><div><strong>Tech for Easy Life</strong><small>Ideas. Made real. Together.</small></div></div><nav class="nav-scroll" aria-label="Workspace">${navLink('guide','Start here','info')}<div class="nav-label">Your day</div>${navLink('home','Home','home')}${navLink('tasks','My tasks','task')}${navLink('attendance','Attendance','clock')}${navLink('leave','Time off','leave')}${navLink('calendar','Team calendar','calendar')}${navLink('people','People','people')}${navLink('meetings','Meetings','meeting')}<div class="nav-label">Team chat</div>${channels.map(c=>`<a class="nav-link ${route==='channel/'+c.id?'active':''}" href="#channel/${encodeURIComponent(c.id)}" ${route==='channel/'+c.id?'aria-current="page"':''}>${icon('hash')}<span>${esc(c.name)}</span></a>`).join('')}<details class="nav-more" ${['documents','grievances','exits','reports','performance','hr'].includes(route)?'open':''}><summary>More tools ${icon('chevron')}</summary>${navLink('documents','Policies & documents','document')}${navLink('grievances','HR desk & tickets','shield')}${navLink('performance','Feedback','heart')}${canReport()?navLink('reports','Team reports','chart'):''}${isHR()?navLink('hr','People admin','settings'):''}${navLink('exits','Leaving the team','briefcase')}</details></nav><a href="#account" class="sidebar-user">${avatar(user,'dark')}<span><strong>${esc(user.name)}</strong><small>${esc(user.designation||roles[user.role]||human(user.role))}</small></span></a></aside><div class="content"><header class="topbar"><div class="btn-row"><button class="icon-btn menu-btn" data-action="toggle-menu" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button><div class="breadcrumb"><span>TEL OS</span><span class="crumb-slash">/</span><strong>${esc(route.startsWith('channel/')?'Team chat':titleMap[route]||'Workspace')}</strong></div></div><div class="top-actions"><a class="help-link" href="#guide">${icon('info')}<span>Help & guide</span></a><span class="date-label">${esc(new Intl.DateTimeFormat('en-IN',{timeZone:TZ,weekday:'short',day:'numeric',month:'long'}).format(new Date()))}</span><a class="icon-btn" href="#notifications" aria-label="Notification centre${unread?', '+unread+' unread':''}">${icon('bell')}${unread?'<span class="dot"></span>':''}</a><a href="#account" aria-label="My account">${avatar(user)}</a></div></header>${!navigator.onLine?'<div class="offlinestate">You are offline. Reconnect to save changes.</div>':''}<main id="main" class="page" tabindex="-1"><div class="loading-message">Opening your workspace…</div><div class="loading-grid"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div></main></div></div>`;
}
async function boot(){if(!user){renderLogin();return;}if(user.must_change_password){app.innerHTML='<main id="main" class="startup"><img class="tel-logo" src="/tel-logo.webp" alt="TEL" width="183" height="96"><h1>Secure your account</h1><p>Choose your personal password to enter TEL OS.</p><button class="btn" data-action="logout">Sign out</button></main>';passwordDialog(true);return;}const [p,c,n]=await Promise.all([api('/api/people'),api('/api/channels'),api('/api/notifications')]);people=p.people||[];channels=c.channels||[];notifications=n.notifications||[];unread=n.unread||0;await navigate();}
async function navigate(){if(!user||user.must_change_password)return;route=decodeURIComponent(location.hash.replace(/^#/,'')||'home');const allowed=['home','guide','tasks','attendance','leave','calendar','people','meetings','documents','grievances','hr','reports','performance','exits','notifications','account','monitor','marketing-reports','images','connections','website-team','founder-updates'];if(!allowed.includes(route)&&!route.startsWith('channel/'))route='home';shell();const token=++pageToken;try{let html;switch(route){case'founder-updates':html=await founderUpdatesPage();break;case'connections':html=await connectionsPage();break;case'website-team':html=await websiteTeamPage();break;case'monitor':html=await monitorPage();break;case'marketing-reports':html=await marketingReportsPage();break;case'images':html=await imagesPage();break;case'home':html=await homePage();break;case'guide':html=await guidePage();break;case'tasks':html=await tasksPage();break;case'attendance':html=await attendancePage();break;case'leave':html=await leavePage();break;case'calendar':html=await calendarPage();break;case'people':html=peoplePage();break;case'meetings':html=await meetingsPage();break;case'documents':html=await documentsPage();break;case'grievances':html=await grievancesPage();break;case'hr':html=await hrPage();break;case'reports':html=await reportsPage();break;case'performance':html=await performancePage();break;case'exits':html=await exitsPage();break;case'notifications':html=await notificationsPage();break;case'account':html=await accountPage();break;default:html=await channelPage(route.slice(8));}if(token!==pageToken||!user)return;$('#main').innerHTML=html;document.title=(route.startsWith('channel/')?'Team channels':$('#main h1')?.textContent||'Workspace')+' · TEL OS';bindPage();updateTimers();}catch(err){if(token!==pageToken||!user)return;$('#main').innerHTML=`<div class="error-page"><div class="empty-icon">${icon('info')}</div><h1>Unable to open this view</h1><p class="muted">${esc(err.message)}</p>${button('Try again','refresh','primary')} <a class="btn" href="#home">Mission Control</a></div>`;}}
async function refresh(){if(!user)return;const [p,n]=await Promise.all([api('/api/people'),api('/api/notifications')]);people=p.people||people;const currentPerson=people.find(p=>p.id===user.id);if(currentPerson)user={...user,...currentPerson};notifications=n.notifications||[];unread=n.unread||0;await navigate();}
function stat(label,value,note,glyph){return `<div class="stat"><div class="stat-head"><span>${esc(label)}</span>${icon(glyph)}</div><div class="stat-value">${esc(value)}</div><div class="stat-note">${esc(note)}</div></div>`;}
function taskRow(t){return `<div class="row"><div class="row-main"><strong>${esc(t.title)}</strong><small>${esc(t.assignee_name||nameOf(t.assignee_id))} · Due ${esc(date(t.deadline))}</small></div>${badge(t.overdue?'overdue':t.status)}<button class="icon-btn" data-action="task-details" data-id="${esc(t.id)}" aria-label="Open assignment ${esc(t.title)}">${icon('chevron')}</button></div>`;}
function crewWidget(){const working=people.filter(p=>p.crew_status==='working');return `<section class="panel"><div class="panel-header"><h2>Crew availability</h2><a class="link-btn" href="#people">View all</a></div><div class="panel-body"><span class="badge green">${working.length} working now</span> <span class="small muted">of ${people.length} team members</span></div><div class="mini-people">${people.slice(0,18).map(p=>`<div class="mini-person ${esc(p.crew_status||p.status)}" title="${esc(p.name+' · '+human(p.crew_status||'offline'))}">${avatar(p)}<small>${esc(p.name.split(' ')[0])}</small></div>`).join('')}</div><div class="row"><div class="row-main"><small>Presence reflects work status, not whether someone is signed in.</small></div></div></section>`;}
function clockTime(s){s=Math.max(0,Math.floor(s||0));return String(Math.floor(s/3600)).padStart(2,'0')+':'+String(Math.floor(s/60)%60).padStart(2,'0')+':'+String(s%60).padStart(2,'0');}
function activeSeconds(s){if(!s)return 0;return Number(s.active_seconds||0)+(s.state==='working'&&s.active_started_at?Math.max(0,Math.floor((Date.now()-new Date((s.calculated_at||s.active_started_at)).getTime())/1000)):0);}
function clockWidget(a){const s=a.current,total=(a.attendance||[]).filter(x=>x.user_id===user.id&&x.work_date===today()).reduce((sum,x)=>sum+activeSeconds(x),0),state=s?.state||((user.status==='on_leave'||person(user.id)?.crew_status==='on_leave')?'on_leave':'offline');records.attendance=a;return `<section class="panel panel-pad clock-panel"><div class="btn-row" style="justify-content:space-between"><span class="section-title" style="margin:0">Your workday</span>${badge(state==='break'?'on_break':state)}</div><div class="clock-time" data-clock>${esc(clockTime(total))} <small>/ 4h</small></div><div class="small muted">Active time today · IST</div><div class="clock-meta"><span>Flexible daily target</span><span data-clock-percent>${Math.min(100,Math.round(total/144))}%</span></div><progress class="clock-progress" max="14400" value="${Math.min(total,14400)}" aria-label="Progress toward four active hours"></progress><div class="btn-row" style="margin-top:20px">${!s&&state==='on_leave'?'<span class="small muted">On leave · HR can update your return status.</span>':!s?`<button class="btn primary" data-action="clock" data-value="clock_in">${icon('clock')}Clock in</button>`:s.state==='working'?button('Take a break','clock','primary','data-value="pause"'):button('Resume work','clock','primary','data-value="resume"')}${s?button('Clock out','clock','','data-value="clock_out"'):''}<a class="btn" href="#attendance">History</a></div></section>`;}
function departmentWorkspace(){
 const department=String(user.department||'').toLowerCase();
 if(isFounder())return {key:'leadership',name:'Leadership',title:'Your organisation, at a glance.',copy:'See how each department is doing, remove blockers, and make sure every responsibility has an owner.',actions:[['Team reports','reports','chart'],['Manage people','hr','people'],['Assign work','new-task','task','action']]};
 if(department==='hr')return {key:'hr',name:'HR',title:'Keep people supported and work organised.',copy:isHR()?'Welcome your teammates, keep records accurate, and move time-off and attendance reviews forward.':'Find your people-operations tasks and keep your reporting lead informed.',actions:isHR()?[['Add team member','new-person','people','action'],['Review time off','leave','leave'],['Check attendance','attendance','clock']]:[['My HR tasks','tasks','task'],['Team calendar','calendar','calendar'],['HR channel',departmentChannel(),'hash']]};
 if(department==='marketing')return {key:'marketing',name:'Marketing',title:isLead()?'Give creative work a clear path to delivery.':'Turn your next idea into finished work.',copy:isLead()?'Assign clear outcomes, review submitted work, and plan around your team’s availability.':'See what is assigned to you, follow the brief, and submit your output for your lead to review.',actions:isLead()?[['Assign marketing task','new-task','task','action'],['Review team tasks','tasks','document'],['Marketing channel',departmentChannel(),'hash']]:[['My marketing tasks','tasks','task'],['Marketing channel',departmentChannel(),'hash'],['My availability','calendar','calendar']]};
 if(department==='finance')return {key:'finance',name:'Finance',title:'Keep finance responsibilities clear and coordinated.',copy:'Your space for assigned finance work, review notes, policies and availability.',actions:[['Finance tasks','tasks','task'],[onLeaveToday()?'View my availability':'Plan my availability','calendar','calendar'],['Finance channel',departmentChannel(),'hash']]};
 if(department==='strategy')return {key:'strategy',name:'Strategy',title:'Turn research into decisions the team can use.',copy:'Follow your research brief, document your findings, and submit clear analysis to your reporting lead.',actions:[['My research tasks','tasks','task'],['Policies & reference notes','documents','document'],['Team coordination',departmentChannel(),'hash']]};
 return {key:'team',name:user.department||'Your team',title:'Know your work and keep your team in sync.',copy:'Find your assigned work, see when to start, and share your progress with your reporting lead.',actions:[['My tasks','tasks','task'],['Team calendar','calendar','calendar'],['Team channel',departmentChannel(),'hash']]};
}
function departmentChannel(){return 'channel/'+(channels.find(c=>String(c.department||'').toLowerCase()===String(user.department||'').toLowerCase())?.id||channels.find(c=>c.id==='general')?.id||'general');}
function onLeaveToday(){return user.status==='on_leave'||person(user.id)?.crew_status==='on_leave';}
function departmentIntro(workspace){return `<section class="department-intro department-${workspace.key}" data-department-home="${workspace.key}"><div><span class="department-tag">${icon(workspace.key==='leadership'?'chart':workspace.key==='hr'?'people':workspace.key==='marketing'?'task':workspace.key==='finance'?'briefcase':'document')}${esc(workspace.name)} workspace</span><h2>${esc(workspace.title)}</h2><p>${esc(workspace.copy)}</p></div><span class="department-role">${esc(user.designation||roles[user.role]||human(user.role))}</span></section>`;}
function departmentQuickPaths(workspace){return `<div class="quick-paths department-quick-paths">${workspace.actions.map(([label,target,glyph,kind])=>kind==='action'?`<button data-action="${esc(target)}">${icon(glyph)}<span><strong>${esc(label)}</strong><small>${target==='new-person'?'Create an individual account':'Set an owner and expected result'}</small></span>${icon('chevron')}</button>`:`<a href="#${esc(target)}">${icon(glyph)}<span><strong>${esc(label)}</strong><small>${target==='tasks'?'Open work, submissions and feedback':target==='reports'?'Delivery and departmental overview':target==='hr'?'Accounts, profiles and access':target==='leave'?'Requests waiting for a decision':target==='attendance'?'Start times and official records':target==='documents'?'Read the team’s working guidance':target==='calendar'?'Leave, exams and working plans':'Updates and shared context'}</small></span>${icon('chevron')}</a>`).join('')}</div>`;}
function homeDepartmentStats(workspace,tasks,leaves,extra){
 const active=tasks.filter(t=>t.status!=='done'),review=tasks.filter(t=>t.status==='review'),done=tasks.filter(t=>t.status==='done'),overdue=active.filter(t=>t.overdue);
 if(workspace.key==='hr'&&isHR()){const waiting=leaves.filter(l=>l.status==='pending_hr'&&l.user_id!==user.id&&l.leader_id!==user.id),corrections=(extra.corrections||[]).filter(c=>c.status==='pending'&&c.user_id!==user.id);return `<div class="stats">${stat('People in the team',people.filter(p=>!['exited','suspended'].includes(p.status)).length,'Active and on-leave accounts','people')}${stat('Time off to verify',waiting.length,'After an independent lead review','leave')}${stat('Corrections to review',corrections.length,'Official attendance requests','clock')}${stat('Status reviews pending',(extra.statusRequests||[]).filter(r=>r.state==='pending').length,'Independent founder decision','shield')}</div>`;}
 if(workspace.key==='leadership'){const report=extra.summary||{};return `<div class="stats">${stat('Open tasks',report.active_tasks??active.length,'Across the organisation','task')}${stat('Past deadline',report.overdue_tasks??overdue.length,'Work that needs a next step','clock')}${stat('Waiting for review',report.pending_reviews??review.length,'Submitted deliverables','document')}${stat('Time-off reviews',report.pending_leaves??leaves.filter(l=>['pending_lead','pending_hr'].includes(l.status)).length,'Department and HR decisions','leave')}</div>`;}
 if(workspace.key==='strategy')return `<div class="stats">${stat('My research tasks',active.length,'Current assigned deliverables','document')}${stat('In progress',tasks.filter(t=>t.status==='working').length,'Research under way','task')}${stat('Awaiting feedback',review.length,'Submitted to your reviewer','people')}${stat('Completed',done.length,'Tasks marked done','check')}</div>`;
 if(workspace.key==='finance')return `<div class="stats">${stat('Finance tasks',active.length,'Open responsibilities','briefcase')}${stat('Waiting for review',review.length,'Submitted finance work','document')}${stat('Completed',done.length,'Tasks marked done','check')}${stat('Availability',onLeaveToday()?'On leave':'Available',onLeaveToday()?'Return arrangements stay with HR':'Check your working plan','calendar')}</div>`;
 return `<div class="stats">${stat(workspace.key==='marketing'?(isLead()?'Team marketing tasks':'My marketing tasks'):'Open tasks',active.length,isLead()?'Within your department':'Assigned to you','task')}${stat(isLead()?'Work to review':'Awaiting feedback',review.length,'Formal submissions','document')}${stat('Needs a deadline update',overdue.length,'Discuss the next step with your lead','clock')}${stat('Completed',done.length,'Tasks marked done','check')}</div>`;
}
function departmentTaskPanel(workspace,tasks){const active=tasks.filter(t=>t.status!=='done'),title=workspace.key==='marketing'?(isLead()?'Marketing work to move forward':'Your next marketing deliverables'):workspace.key==='strategy'?'Research & analysis deliverables':workspace.key==='finance'?'Finance responsibilities':'Your task overview';return `<section class="panel department-work-panel"><div class="panel-header"><h2>${esc(title)}</h2><a class="link-btn" href="#tasks">Open tasks ${icon('arrow')}</a></div>${active.length?active.slice(0,5).map(taskRow).join(''):empty(workspace.key==='strategy'?'Your next research brief will appear here':workspace.key==='finance'?'No open finance tasks':'No open tasks yet',workspace.key==='finance'&&onLeaveToday()?'You are on leave. Agree your return and any handovers with HR before resuming work.':isLead()&&workspace.key==='marketing'?'Create a task with a clear owner, deadline and expected result.':'Your reporting lead will add work here with a clear expected result and reviewer.',workspace.key==='finance'?'briefcase':workspace.key==='strategy'?'document':'task',isLead()&&workspace.key==='marketing'?plusButton('Assign marketing task','new-task'):'')}</section>`;}
function hrWorkPanel(leaves,extra){const waiting=leaves.filter(l=>l.status==='pending_hr'&&l.user_id!==user.id&&l.leader_id!==user.id),corrections=(extra.corrections||[]).filter(c=>c.status==='pending'&&c.user_id!==user.id);return `<section class="panel department-work-panel"><div class="panel-header"><h2>People actions needing attention</h2><a class="link-btn" href="#hr">People admin</a></div>${waiting.map(l=>`<div class="row"><span class="avatar">${icon('leave')}</span><div class="row-main"><strong>${esc(l.name||nameOf(l.user_id))} · time-off verification</strong><small>${esc(date(l.start_date))}–${esc(date(l.end_date))} · recommended by a lead</small></div><a class="btn small" href="#leave">Review request</a></div>`).join('')}${corrections.map(c=>`<div class="row"><span class="avatar">${icon('clock')}</span><div class="row-main"><strong>${esc(c.name||nameOf(c.user_id))} · attendance correction</strong><small>${esc(date(c.work_date))} · official record review</small></div><a class="btn small" href="#attendance">Review correction</a></div>`).join('')}${!waiting.length&&!corrections.length?empty('The people review queue is clear','New time-off verifications and attendance corrections appear here when someone needs your review.','people'):''}</section><section class="panel panel-pad"><h2>Welcome the next teammate</h2><p class="small muted">Register the member, confirm their department and reporting manager, then share their individual temporary password privately. The beginner guide and policies support their first day.</p>${button('Add team member','new-person','primary')}</section>`;}
function leadershipPanel(summary,tasks){const depts=[...new Set(people.map(p=>p.department).filter(d=>d&&d!=='Leadership'))],workload=summary?.department_workload||[];return `<section class="panel department-work-panel"><div class="panel-header"><h2>Departments at a glance</h2><a class="link-btn" href="#reports">Open team reports</a></div><div class="department-overview-grid">${depts.map(department=>{const members=people.filter(p=>p.department===department&&!['exited','suspended'].includes(p.status)),work=workload.find(w=>w.department===department),lead=members.find(p=>['hr_lead','team_lead','finance_head'].includes(p.role)),manager=lead||person(members.find(p=>p.manager_id)?.manager_id);return `<article class="department-overview-card"><h3>${esc(department)}</h3><p>${members.length} ${members.length===1?'member':'members'}<span>${members.filter(p=>p.crew_status==='on_leave').length} on leave</span></p><div class="department-card-counts"><span><strong>${esc(work?.total||0)}</strong> open tasks</span><span><strong>${esc(work?.review||0)}</strong> in review</span></div><small>${manager?`${lead?'Department lead':'Reporting lead'}: ${esc(manager.name)}`:'Reporting lead can be set in People admin.'}</small></article>`;}).join('')}</div></section><section class="panel"><div class="panel-header"><h2>Work needing a leadership check</h2><a class="link-btn" href="#tasks">All tasks</a></div>${tasks.filter(t=>t.overdue||t.status==='review').length?tasks.filter(t=>t.overdue||t.status==='review').slice(0,5).map(taskRow).join(''):empty('No delivery blockers are showing','Past-deadline tasks and submitted work will appear here so you can help the right team move forward.','chart')}</section>`;}
function departmentSupportPanel(workspace){const manager=user.manager_id?person(user.manager_id):null;if(workspace.key==='strategy')return `<section class="panel panel-pad"><h2>Work with your reporting lead</h2><p class="small muted">${manager?`Your reporting lead is ${esc(manager.name)}. `:''}Keep findings and sources together in your deliverable. Submit it on the task so your lead can review the result and give feedback.</p><a class="btn" href="#tasks">Open research tasks</a></section>`;if(workspace.key==='finance')return `<section class="panel panel-pad"><h2>Finance coordination</h2><p class="small muted">Keep task owners, review notes and handover responsibilities recorded. Check the team calendar before relying on someone’s availability.</p><div class="btn-row"><a class="btn" href="#documents">Policies & documents</a><a class="btn" href="#calendar">Team calendar</a></div></section>`;return `<div class="note">${icon('heart')}<span><strong>Have classes or exams?</strong><br>Update your availability or request time off early so your lead can plan around it.</span></div>`;}
async function homePage(){
 const workspace=departmentWorkspace(),extraRequests=workspace.key==='leadership'?[api('/api/reports')]:workspace.key==='hr'&&isHR()?[api('/api/corrections'),api('/api/status-requests')]:[];
 const [t,a,l,m,s,p,...extraResults]=await Promise.all([api('/api/tasks'),api('/api/attendance'),api('/api/leaves'),api('/api/meetings'),api('/api/schedules'),api('/api/people/'+encodeURIComponent(user.id)),...extraRequests]);
 records.tasks=t.tasks||[];records.leaves=l.leaves||[];records.meetings=m.meetings||[];records.schedules=s;records.onboarding=p.onboarding||{};
 const extra={summary:extraResults[0]?.summary,corrections:extraResults[0]?.corrections||[],statusRequests:extraResults[1]?.requests||[]},upcoming=records.meetings.filter(x=>new Date(x.starts_at)>=new Date()).sort((x,y)=>x.starts_at.localeCompare(y.starts_at)).slice(0,3);
 const mainWork=workspace.key==='leadership'?leadershipPanel(extra.summary,records.tasks):workspace.key==='hr'&&isHR()?hrWorkPanel(records.leaves,extra):departmentTaskPanel(workspace,records.tasks);
 return pageHeading(`Welcome, ${user.name.split(' ')[0]}.`,workspace.key==='leadership'?'Your company overview, with the right next step for every department.':`Your ${workspace.name.toLowerCase()} workspace, with your schedule and next steps in one place.`,'<a class="btn" href="#guide">'+icon('info')+'Start here</a>',`${workspace.name.toUpperCase()} · TEL OS`)+departmentIntro(workspace)+(workspace.key==='finance'&&onLeaveToday()?`<section class="department-leave-banner" data-finance-leave>${icon('leave')}<div><h2>You’re on leave.</h2><p>There is no scheduled clock-in requirement while this status applies. Use your calendar to review availability and agree return arrangements with HR.</p></div><a class="btn" href="#calendar">View availability</a></section>`:'')+guideBanner(records.onboarding)+`<div class="daily-focus">${clockWidget(a)}${scheduleSummary(s)}</div>`+departmentQuickPaths(workspace)+homeDepartmentStats(workspace,records.tasks,records.leaves,extra)+`<div class="grid-two"><div class="stack">${mainWork}<section class="panel"><div class="panel-header"><h2>${workspace.key==='leadership'?'Upcoming team meetings':'Upcoming meetings'}</h2><a class="link-btn" href="#meetings">All meetings</a></div>${upcoming.length?upcoming.map(x=>`<div class="row"><span class="avatar">${icon('meeting')}</span><div class="row-main"><strong>${esc(x.title)}</strong><small>${esc(datetime(x.starts_at))} IST · ${x.participants?.length||0} participants</small></div>${button('Open','meeting-details','small',`data-id="${esc(x.id)}"`)}</div>`).join(''):empty('Your calendar is clear','Meeting times, links and notes appear here when one is scheduled.','meeting')}</section></div><div class="stack">${crewWidget()}${departmentSupportPanel(workspace)}</div></div>`;
}
async function tasksPage(){const {tasks=[]}=await api('/api/tasks');records.tasks=tasks;const filtered=tasks.filter(t=>taskFilter==='mine'?t.assignee_id===user.id:taskFilter==='overdue'?t.overdue:taskFilter==='review'?t.status==='review':true);return pageHeading('My tasks','Open a task to see what to do, who reviews it, and when it is due.',isLead()?plusButton('Assign work','new-task'):'','OPERATIONS')+`<div class="tabs" role="tablist">${[['all','All assignments'],['mine','Assigned to me'],['review','Ready for review'],['overdue','Overdue']].map(([v,l])=>`<button class="tab ${taskFilter===v?'active':''}" data-action="task-filter" data-value="${v}" role="tab" aria-selected="${taskFilter===v}">${l}</button>`).join('')}</div><div class="kanban">${[['todo','To do'],['working','In progress'],['review','In review'],['revision','Revision required'],['approved','Approved'],['done','Done']].map(([s,label])=>{const lane=filtered.filter(t=>t.status===s);return `<section class="kanban-column"><h2 class="kanban-title">${label}<span>${lane.length}</span></h2>${lane.length?lane.map(t=>`<button class="task-card" data-action="task-details" data-id="${esc(t.id)}"><div class="btn-row"><span class="badge ${t.priority==='urgent'?'red':t.priority==='high'?'amber':''}">${esc(human(t.priority))}</span>${t.overdue?'<span class="badge red">Overdue</span>':''}</div><h3>${esc(t.title)}</h3><div class="task-deadline">${icon('calendar')} Due ${esc(date(t.deadline))}</div><div class="task-meta"><span>${esc(t.assignee_name||nameOf(t.assignee_id))}</span>${avatar(t.assignee_name||nameOf(t.assignee_id))}</div></button>`).join(''):'<div class="empty small" style="padding:20px 5px">No assignments here yet.</div>'}</section>`;}).join('')}</div><p class="hint">Messages keep the team connected. Submit your deliverable on the assignment to move work into review.</p>`;}
function taskDialog(id){const t=records.tasks.find(x=>x.id===id);if(!t)return;const own=t.assignee_id===user.id,reviewer=t.assignee_id!==user.id&&(isFounder()||t.leader_id===user.id);let actions='';if(own&&['todo','revision'].includes(t.status))actions+=button('Start work','task-action','primary',`data-id="${esc(id)}" data-value="start"`);if(own&&['working','revision'].includes(t.status))actions+=button('Submit deliverable','task-submit','primary',`data-id="${esc(id)}"`);if(reviewer&&t.status==='review')actions+=button('Approve','task-action','primary',`data-id="${esc(id)}" data-value="approve"`)+button('Request revision','task-revision','',`data-id="${esc(id)}"`);if((own||reviewer)&&t.status==='approved')actions+=button('Mark done','task-action','primary',`data-id="${esc(id)}" data-value="complete"`);openDialog(t.title,`<div class="btn-row">${badge(t.status)}<span class="badge">${esc(human(t.priority))} priority</span></div><div class="task-details-grid"><div><small>Assigned to</small>${esc(t.assignee_name||nameOf(t.assignee_id))}</div><div><small>Reporting leader</small>${esc(t.leader_name||nameOf(t.leader_id))}</div><div><small>Deadline</small>${esc(date(t.deadline,true))}</div><div><small>Department</small>${esc(t.department)}</div></div><h3>Description</h3><p class="task-description">${esc(t.description||'No additional description.')}</p><h3>Expected deliverable</h3><p class="task-description">${esc(t.expected_deliverable)}</p>${t.submission?`<h3>Submitted deliverable</h3><div class="note pre">${esc(t.submission)}</div>`:''}${t.feedback?`<h3 style="margin-top:20px">Review feedback</h3><p class="task-description">${esc(t.feedback)}</p>`:''}<div class="form-actions">${actions||'<span class="small muted">No action needed from you at this stage.</span>'}</div>`);}
function newTask(){modalForm('Create an assignment',`<div class="form-grid">${field('Task title','title','text',{required:true,wide:true,maxlength:180})}${field('Assigned employee','assignee_id','select',{required:true,value:people.find(p=>p.id!==user.id&&p.status==='active'&&(isFounder()||p.department===user.department))?.id,options:peopleOptions(p=>p.status==='active'&&(isFounder()||p.department===user.department))})}${field('Reporting team leader','leader_id','select',{required:true,value:user.id,options:peopleOptions(p=>['founder','hr_lead','team_lead','finance_head'].includes(p.role))})}${field('Priority','priority','select',{options:[['normal','Normal'],['high','High'],['urgent','Urgent']]})}${field('Deadline','deadline','date',{required:true,min:today()})}${field('Description','description','textarea',{required:true,wide:true})}${field('Expected deliverable','expected_deliverable','textarea',{required:true,wide:true,hint:'Describe what the reviewer should receive, including the format or link.'})}</div>`,b=>api('/api/tasks','POST',b),{submit:'Create assignment',description:'Assign a clear outcome. Team members submit deliverables here before the review begins.'});}
async function legacyAttendancePage(){const [a,c]=await Promise.all([api('/api/attendance'),api('/api/corrections')]);records.attendance=a;records.corrections=c.corrections||[];return pageHeading('Attendance','Clock in at your scheduled time, pause for breaks, and clock out when finished.',button('Request correction','new-correction'),'YOUR WORKDAY')+`<div class="grid-two"><div class="stack"><section class="panel"><div class="panel-header"><h2>Attendance history</h2><span class="small muted">All times IST</span></div>${a.attendance?.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Team member / Date</th><th>Clock in / out</th><th>Active time</th><th>Status</th></tr></thead><tbody>${a.attendance.map(s=>`<tr><td>${esc(s.name||nameOf(s.user_id))}<small>${esc(date(s.work_date,true))}</small></td><td>${s.source==='correction'?'HR correction':esc(time(s.clock_in))}<small>${s.source==='correction'?'Adjusted daily total':esc(time(s.clock_out))}</small></td><td>${esc(hours(activeSeconds(s)))}<small>${esc(hours(s.break_seconds))} breaks</small></td><td>${badge(s.state==='break'?'on_break':s.state)}</td></tr>`).join('')}</tbody></table></div>`:empty('Your attendance starts here','Clock in when you begin, pause for breaks, and clock out when you finish.','clock')}</section><section class="panel"><div class="panel-header"><h2>Correction requests</h2></div>${records.corrections.length?records.corrections.map(c=>`<article class="list-card"><div class="list-card-head"><div><h3>${esc(c.name||nameOf(c.user_id))} · ${esc(date(c.work_date))}</h3><div class="small muted">Requested active time: ${esc(hours(c.requested_seconds))}</div></div>${badge(c.status)}</div><p class="pre">${esc(c.reason)}</p>${c.review_note?`<p class="pre"><strong>Review:</strong> ${esc(c.review_note)}</p>`:''}${isHR()&&c.user_id!==user.id&&c.status==='pending'?`<div class="btn-row">${button('Approve','correction-review','primary small',`data-id="${esc(c.id)}" data-value="approve"`)}${button('Reject','correction-review','small',`data-id="${esc(c.id)}" data-value="reject"`)}</div>`:''}</article>`).join(''):empty('No correction requests','Forgot to clock out? Submit a correction with the actual active time and a reason.','document')}</section></div><div class="stack">${clockWidget(a)}<div class="note">${icon('info')}<span>The daily target is approximately four active hours. Plan around classes and exams; attendance alone does not determine performance.</span></div></div></div>`;}
function newCorrection(){modalForm('Request an attendance correction',field('Work date','work_date','date',{required:true,max:today(),value:today()})+field('Actual active hours','hours','number',{required:true,min:0,max:24,step:.25,hint:'Exclude breaks. Your reviewer will check the requested total.'})+field('Reason for correction','reason','textarea',{required:true}),b=>api('/api/corrections','POST',{work_date:b.work_date,requested_seconds:Math.round(Number(b.hours)*3600),reason:b.reason}),{submit:'Submit correction'});}
async function leavePage(){const {leaves=[]}=await api('/api/leaves');records.leaves=leaves;return pageHeading('Time off','Request leave for exams, health or personal commitments. Track the decision here.',plusButton('Request leave','new-leave'),'PEOPLE & AVAILABILITY')+`<div class="note" style="margin-bottom:22px">${icon('calendar')}<span>Requests go to your reporting leader, then HR. Approved leave appears on the shared availability calendar. Private reasons stay with the authorised reviewers.</span></div><section class="panel"><div class="panel-header"><h2>Leave requests</h2><span class="small muted">${leaves.length} visible to you</span></div>${leaves.length?leaves.map(l=>`<article class="list-card"><div class="list-card-head"><div><h3>${esc(l.name||nameOf(l.user_id))} <span class="muted">· ${esc(human(l.type))} leave</span></h3><div class="small muted">${esc(date(l.start_date,true))} – ${esc(date(l.end_date,true))}</div></div>${badge(l.status)}</div><p class="pre">${esc(l.reason||'Private reason')}</p>${l.handover_to?`<div class="small">Handover to <strong>${esc(nameOf(l.handover_to))}</strong>${l.handover_notes?': '+esc(l.handover_notes):''}</div>`:''}${l.leader_note||l.hr_note?`<p class="pre small" style="margin-top:10px">${esc(l.hr_note||l.leader_note)}</p>`:''}<div class="list-card-footer"><span class="small muted">${esc(l.department||'')}</span><div class="btn-row">${l.user_id!==user.id&&l.status==='pending_lead'&&(isFounder()||person(l.user_id)?.manager_id===user.id||(isLead()&&l.department===user.department))?button('Recommend to HR','leave-review','primary small',`data-id="${esc(l.id)}" data-value="recommend"`)+button('Reject','leave-review','small',`data-id="${esc(l.id)}" data-value="reject"`):''}${l.user_id!==user.id&&l.status==='pending_hr'&&isHR()&&l.leader_id!==user.id?button('Approve leave','leave-review','primary small',`data-id="${esc(l.id)}" data-value="approve"`)+button('Reject','leave-review','small',`data-id="${esc(l.id)}" data-value="reject"`):''}</div></div></article>`).join(''):empty('No leave requests yet','Submit exam dates early and choose a handover person for responsibilities that need cover.','leave')}</section>`;}
function newLeave(){modalForm('Request leave',`<div class="form-grid">${field('Leave category','type','select',{required:true,wide:true,options:[['examination','Examination leave'],['academic','Academic obligations'],['medical','Medical leave'],['personal','Personal leave'],['emergency','Emergency leave']]})}${field('First day','start_date','date',{required:true,value:today()})}${field('Last day','end_date','date',{required:true,value:today()})}${field('Reason for your reviewers','reason','textarea',{required:true,wide:true,hint:'The shared calendar will not display this private reason.'})}${field('Handover to','handover_to','select',{wide:true,options:peopleOptions(p=>p.id!==user.id&&p.status==='active',true)})}${field('Handover notes','handover_notes','textarea',{wide:true,hint:'Shared on the team calendar. Include only work responsibilities.'})}</div>`,b=>{if(b.end_date<b.start_date)throw new Error('The last day must be on or after the first day.');return api('/api/leaves','POST',b);},{submit:'Submit for review'});}
async function calendarPage(){const {calendar={}}=await api('/api/calendar');records.calendar=calendar;const base=new Date(today()+'T12:00:00Z');base.setUTCMonth(base.getUTCMonth()+calendarOffset,1);const year=base.getUTCFullYear(),month=base.getUTCMonth(),offset=(base.getUTCDay()+6)%7,start=new Date(Date.UTC(year,month,1-offset,12));const cells=Array.from({length:42},(_,i)=>{const d=new Date(start);d.setUTCDate(d.getUTCDate()+i);const iso=d.toISOString().slice(0,10);const events=[...(calendar.leaves||[]).filter(x=>x.start_date<=iso&&x.end_date>=iso).map(x=>({name:x.name+' · Leave'})),...(calendar.availability||[]).filter(x=>x.start_date<=iso&&x.end_date>=iso).map(x=>({name:x.name+' · '+human(x.kind),amber:true}))];return `<div class="calendar-day ${d.getUTCMonth()!==month?'outside':''} ${iso===today()?'today':''}"><span class="day-number">${d.getUTCDate()}</span>${events.slice(0,2).map(e=>`<span class="calendar-event ${e.amber?'amber':''}" title="${esc(e.name)}">${esc(e.name)}</span>`).join('')}${events.length>2?`<span class="tiny muted">+${events.length-2} more</span>`:''}</div>`;}).join('');return pageHeading('Team availability','Plan around exams, leave, and the people your work depends on.',plusButton('Share availability','new-availability'),'SHARED CALENDAR')+`<div class="calendar-layout"><section class="panel"><div class="panel-header"><h2>${esc(new Intl.DateTimeFormat('en-IN',{timeZone:'UTC',month:'long',year:'numeric'}).format(base))}</h2><div class="btn-row"><button class="icon-btn" data-action="calendar-prev" aria-label="Previous month">←</button>${button('Today','calendar-today','small')}<button class="icon-btn" data-action="calendar-next" aria-label="Next month">→</button></div></div><div class="calendar-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<div class="calendar-dow">${x}</div>`).join('')}${cells}</div><div class="panel-body"><div class="btn-row"><span class="badge green">Approved leave</span><span class="badge amber">Shared availability</span></div></div></section><div class="stack"><section class="panel"><div class="panel-header"><h2>On leave</h2></div>${calendar.on_leave?.length?calendar.on_leave.map(p=>`<div class="row">${avatar(p)}<div class="row-main"><strong>${esc(p.name)}</strong><small>${esc(p.department)} · Return date not set</small></div>${badge('on_leave')}</div>`).join(''):empty('No indefinite leave','Dated approved leave appears below.','leave')}</section><section class="panel"><div class="panel-header"><h2>Approved leave & handovers</h2></div>${calendar.leaves?.length?calendar.leaves.map(l=>`<div class="row"><div class="row-main"><strong>${esc(l.name)}</strong><small>${esc(date(l.start_date))} – ${esc(date(l.end_date))}</small>${l.handover_to?`<small>Cover: ${esc(l.handover_name||nameOf(l.handover_to))}</small>`:''}${l.handover_notes?`<p class="small pre" style="margin-top:7px">${esc(l.handover_notes)}</p>`:''}</div>${badge('approved')}</div>`).join(''):empty('No approved leave scheduled','Approved requests update this calendar automatically.','calendar')}</section></div></div><section class="panel" style="margin-top:24px"><div class="panel-header"><h2>Shared schedules & commitments</h2></div>${calendar.availability?.length?calendar.availability.map(x=>`<div class="row"><div class="row-main"><strong>${esc(x.name)} · ${esc(human(x.kind))}</strong><small>${esc(date(x.start_date))} – ${esc(date(x.end_date))}</small><p class="small pre" style="margin:7px 0 0">${esc(x.notes)}</p></div>${x.user_id===user.id?button('Remove','remove-availability','small',`data-id="${esc(x.id)}"`):''}</div>`).join(''):empty('Keep the team in the loop','Add your exam period, weekly schedule, or upcoming changes in availability.','people')}</section>`;}
function newAvailability(){modalForm('Share your availability',`<div class="form-grid">${field('Availability type','kind','select',{wide:true,options:[['exam','Exam period'],['unavailable','Unavailable'],['available','Available'],['weekly_schedule','Weekly working schedule']]})}${field('First day','start_date','date',{required:true,value:today()})}${field('Last day','end_date','date',{required:true,value:today()})}${field('Notes for the team','notes','textarea',{wide:true,required:true,hint:'Visible to the team. For a weekly schedule, include your working days and times in IST.'})}</div>`,b=>{if(b.end_date<b.start_date)throw new Error('The last day must be on or after the first day.');return api('/api/availability','POST',b);},{submit:'Update calendar',description:'Sharing availability helps coordination. Request leave separately when approval is needed.'});}
function personCard(p){return `<article class="person-card" data-person="${esc((p.name+' '+p.department+' '+p.designation).toLowerCase())}"><div class="person-card-head">${avatar(p)}${badge(p.crew_status||p.status)}</div><h3>${esc(p.name)}</h3><p class="designation">${esc(p.designation||roles[p.role]||human(p.role))}<br>${esc(p.department)}</p><div class="person-footer"><span>${esc(p.employee_id||'')}</span><span>${p.manager_id?'Reports to '+esc(nameOf(p.manager_id)):'Leadership'}</span></div></article>`;}
function peoplePage(){return pageHeading('Crew directory','Know who owns what, and who is available to help.','','YOUR PEOPLE')+`<div class="filters"><div class="search">${icon('search')}<input id="people-search" type="search" aria-label="Search people" placeholder="Search names, roles, departments"></div><span class="small muted">${people.length} team members · Work status is separate from login status</span></div><div class="people-grid" id="people-grid">${people.map(personCard).join('')}</div><p class="hint" id="people-empty" hidden>No team members match your search.</p>`;}
async function meetingsPage(){const {meetings=[]}=await api('/api/meetings');records.meetings=meetings;return pageHeading('Meetings & calls','Keep the purpose, people, decisions, and follow-up work together.',isHR()||isLead()?plusButton('Schedule / log a call','new-meeting'):'','COLLABORATION')+`<section class="panel"><div class="panel-header"><h2>Meeting schedule & call records</h2><span class="small muted">Times shown in IST</span></div>${meetings.length?meetings.map(m=>`<article class="list-card"><div class="list-card-head"><div><h3>${esc(m.title)}</h3><div class="small muted">${esc(datetime(m.starts_at))} IST · ${m.participants?.length||0} participants${m.kind==='client_call'?' · Client call':''}</div></div>${new Date(m.starts_at)>=new Date()?'<span class="badge green">Upcoming</span>':'<span class="badge">Recorded</span>'}</div><p class="pre">${esc(m.purpose)}</p><div class="list-card-footer"><span class="small muted">${esc(m.department||'Company')}</span><div class="btn-row">${safeURL(m.call_url)?`<a class="btn small" target="_blank" rel="noopener noreferrer" href="${esc(safeURL(m.call_url))}">${icon('meeting')}Join call</a>`:''}${button('Open record','meeting-details','small',`data-id="${esc(m.id)}"`)}</div></div></article>`).join(''):empty('No meetings scheduled','Create a meeting with a clear purpose, or log a client call for future reference.','meeting')}</section>`;}
function newMeeting(){modalForm('Schedule a meeting or log a call',`<div class="form-grid">${field('Title','title','text',{required:true,wide:true,maxlength:160})}${field('Type','kind','select',{options:[['meeting','Team meeting'],['client_call','Client call']]})}${field('Date and time (your device timezone)','starts_at','datetime-local',{required:true})}${field('Purpose','purpose','textarea',{required:true,wide:true})}${field('Call link','call_url','url',{wide:true,placeholder:'https://…',hint:'Use your team’s existing meeting service.'})}${field('Participants','participants','select',{wide:true,multiple:true,options:peopleOptions(),hint:'Select everyone who should attend. Hold Ctrl or Command to choose several.'})}${field('Department','department','select',{options:manageableDepartments()})}${field('Decisions / call notes','decisions','textarea',{wide:true})}${field('Follow-up responsibilities','follow_ups','textarea',{wide:true,hint:'Name the owner and due date. Create assignments for work that needs deliverable review.'})}</div>`,(b,f)=>api('/api/meetings','POST',{...b,starts_at:new Date(b.starts_at).toISOString(),participants:[...f.elements.participants.selectedOptions].map(o=>o.value)}),{submit:'Save meeting record'});}
function meetingDialog(id){const m=records.meetings.find(x=>x.id===id);if(!m)return;openDialog(m.title,`<div class="small muted">${esc(datetime(m.starts_at))} IST · ${esc(m.department||'Company')}</div><h3 style="margin-top:20px">Purpose</h3><p class="pre">${esc(m.purpose)}</p><h3>Participants</h3><p>${(m.participants||[]).map(x=>esc(nameOf(x))).join(', ')||'No participants selected.'}</p><h3>Attendance</h3><p>${(m.attended||[]).map(x=>esc(nameOf(x))).join(', ')||'Not recorded yet.'}</p><h3>Decisions</h3><p class="pre">${esc(m.decisions||'No decisions recorded yet.')}</p><h3>Follow-up responsibilities</h3><p class="pre">${esc(m.follow_ups||'No follow-up recorded yet.')}</p><div class="form-actions">${safeURL(m.call_url)?`<a class="btn" href="${esc(safeURL(m.call_url))}" target="_blank" rel="noopener noreferrer">Join call</a>`:''}${canManageDepartment(m.department)||m.created_by===user.id?button('Update notes & attendance','meeting-edit','primary',`data-id="${esc(id)}"`):''}</div>`);}
function editMeeting(id){const m=records.meetings.find(x=>x.id===id);if(!m)return;modalForm('Update meeting record',field('Decisions','decisions','textarea',{value:m.decisions})+field('Follow-up responsibilities','follow_ups','textarea',{value:m.follow_ups})+`<div class="field"><label>Attendance</label>${(m.participants||[]).map(x=>`<label class="checkline"><input type="checkbox" name="attended" value="${esc(x)}" ${m.attended?.includes(x)?'checked':''}>${esc(nameOf(x))}</label>`).join('')||'<p class="small muted">No participants to mark.</p>'}</div>`,(b,f)=>api('/api/meetings/'+encodeURIComponent(id),'PATCH',{decisions:b.decisions,follow_ups:b.follow_ups,attended:[...f.querySelectorAll('[name="attended"]:checked')].map(x=>x.value)}),{submit:'Update record'});}
async function documentsPage(){const {documents=[]}=await api('/api/documents');records.documents=documents;return pageHeading('Policies & documents','One reference point for how the team works.',isHR()||isLead()?plusButton('Add document','new-document'):'','KNOWLEDGE BASE')+`<div class="document-grid">${documents.map(d=>`<button class="document-card" data-action="document-details" data-id="${esc(d.id)}"><span class="doc-icon">${icon('document')}</span><span><h3>${esc(d.title)}</h3><small>${esc(d.department||'Company')} · Version ${esc(d.version||1)}</small><p>${esc((d.body||'').slice(0,130))}${d.body?.length>130?'…':''}</p></span></button>`).join('')}</div>${!documents.length?`<section class="panel">${empty('Build your shared handbook','Add company policies, departmental guidelines, and practical SOPs.','document')}</section>`:''}`;}
function newDocument(){modalForm('Add a policy or document',field('Document title','title','text',{required:true,maxlength:180})+field('Audience','department','select',{options:manageableDepartments()})+field('Document content','body','textarea',{required:true,rows:12,hint:'Use plain text with clear headings. Do not include passwords or private personnel records.'}),b=>api('/api/documents','POST',b),{submit:'Publish document'});}
async function grievancesPage(){const {grievances=[]}=await api('/api/grievances');records.grievances=grievances;return pageHeading('Confidential concerns','A private route to raise a workplace concern and track its response.',plusButton('Raise a concern','new-grievance'),'CARE & ACCOUNTABILITY')+`<div class="note" style="margin-bottom:22px">${icon('shield')}<span>Concern details are restricted to you and the authorised reviewer. For an HR-related concern, choose “Founders only” when submitting.</span></div><section class="panel"><div class="panel-header"><h2>Your authorised concern records</h2></div>${grievances.length?grievances.map(g=>`<article class="list-card"><div class="list-card-head"><div><h3>${esc(g.title)}</h3><small class="muted">${esc(date(g.created_at,true))}${g.founder_only?' · Founders only':''}</small></div>${badge(g.status)}</div><p class="pre">${esc(g.body)}</p>${g.response?`<div class="note pre"><span><strong>Response</strong><br>${esc(g.response)}</span></div>`:''}${(isFounder()||user.role==='hr_lead')&&g.user_id!==user.id&&g.status!=='resolved'?`<div class="form-actions">${button('Review & respond','grievance-review','small',`data-id="${esc(g.id)}"`)}</div>`:''}</article>`).join(''):empty('No concerns to display','Use this confidential route when a workplace issue needs a documented response.','shield')}</section>`;}
function newGrievance(){modalForm('Raise a confidential concern',field('Subject','title','text',{required:true,maxlength:180})+field('What happened?','body','textarea',{required:true,rows:7,hint:'Share the information needed for a fair review. This record is associated with your account.'})+'<label class="checkline"><input type="checkbox" name="founder_only">Founders only — this concern should bypass HR.</label>',(b,f)=>api('/api/grievances','POST',{title:b.title,body:b.body,founder_only:f.elements.founder_only.checked}),{submit:'Submit concern',description:'Only you and the authorised reviewers can read this record.'});}
async function notificationsPage(){const n=await api('/api/notifications');notifications=n.notifications||[];unread=n.unread||0;return pageHeading('Notification centre','Assignment reminders, approval updates, and important team changes.',notifications.some(n=>!n.read_at)?button('Mark all as read','read-notifications'):'','YOUR INBOX')+`<section class="panel">${notifications.length?notifications.map(n=>`<article class="list-card notification ${!n.read_at?'unread':''}"><div class="list-card-head"><div><h3>${esc(n.title)}</h3><p class="pre">${esc(n.body)}</p><time>${esc(datetime(n.created_at))}</time></div>${!n.read_at?button('Mark read','read-notification','small',`data-id="${esc(n.id)}"`):''}</div>${notificationLink(n.link)?`<a class="link-btn" href="${esc(notificationLink(n.link))}">Open related record →</a>`:''}</article>`).join(''):empty('You’re all caught up','Updates and automatic reminders will appear here as the team gets to work.','bell')}</section>`;}
async function channelPage(id){const c=channels.find(x=>x.id===id);if(!c)throw new Error('This channel is not available to your account.');const {messages=[]}=await api('/api/channels/'+encodeURIComponent(id)+'/messages');records.messages=messages;records.currentChannel=c;const canPost=c.posting_policy!=='announcements'||isFounder()||user.role==='hr_lead';return `<div class="channel-view"><header class="channel-heading"><span class="hash" aria-hidden="true">#</span><div><h1>${esc(c.name)}</h1><p>${esc(c.description)}</p></div></header><div class="message-feed" id="message-feed">${messages.filter(x=>!x.parent_id).map(m=>messageHTML(m,messages.filter(x=>x.parent_id===m.id).length)).join('')||empty('Start the conversation','Use this channel for shared context. Track deliverables and approvals in their dedicated workflows.','people')}</div>${canPost?`<form class="composer" id="message-form"><div class="form-error" role="alert" tabindex="-1"></div><label class="small muted" for="message-input">Message #${esc(c.name)}</label><textarea id="message-input" name="body" required maxlength="4000" placeholder="Share an update with the team…"></textarea><div class="composer-footer"><small>Keep decisions clear. Submit work on its assignment for formal review.</small><button class="btn primary" type="submit">${icon('send')}Send</button></div></form>`:'<div class="note">Announcements are posted by founders and the HR lead. Everyone in this channel can read them.</div>'}</div>`;}
function messageHTML(m,replies=0){return `<article class="message">${avatar(m.name||nameOf(m.user_id))}<div class="message-body"><div class="message-meta"><strong>${esc(m.name||nameOf(m.user_id))}</strong><time>${esc(datetime(m.created_at))}</time></div><div class="message-content">${esc(m.body)}</div>${!m.parent_id&&(records.currentChannel?.posting_policy!=='announcements'||isFounder()||user.role==='hr_lead')?`<button class="thread-btn" data-action="open-thread" data-id="${esc(m.id)}">${replies?replies+' '+(replies===1?'reply':'replies'):'Reply in thread'}</button>`:''}</div></article>`;}
function threadDialog(id){const m=records.messages.find(x=>x.id===id);if(!m)return;const replies=records.messages.filter(x=>x.parent_id===id);openDialog('Thread',messageHTML({...m,parent_id:'root'})+`<div class="section-title" style="margin:18px 0">${replies.length} replies</div>${replies.map(x=>messageHTML(x)).join('')}<form id="thread-form" class="composer"><div class="form-error" role="alert" tabindex="-1"></div><label class="small muted" for="thread-body">Reply to ${esc(m.name||nameOf(m.user_id))}</label><textarea id="thread-body" name="body" maxlength="4000" required></textarea><div class="composer-footer"><span class="small muted">Keep this conversation together.</span><button class="btn primary" type="submit">Reply</button></div></form>`);$('#thread-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button');b.disabled=true;try{await api('/api/channels/'+encodeURIComponent(records.currentChannel.id)+'/messages','POST',{body:f.elements.body.value,parent_id:id});const r=await api('/api/channels/'+encodeURIComponent(records.currentChannel.id)+'/messages');records.messages=r.messages;threadDialog(id);}catch(err){formError(f,err.message);b.disabled=false;}});}
async function hrPage(){if(!isHR())throw new Error('HR Command is restricted to authorised administrators.');const {requests=[]}=await api('/api/status-requests');records.statusRequests=requests;return pageHeading('People admin','Add members, update profiles, and manage access with a recorded review.',plusButton('Register employee','new-person'),'PEOPLE ADMINISTRATION')+`<div class="onboarding-steps"><span>Recruitment & selection</span><span>HR registration</span><span>Individual credentials</span><span>Policy orientation</span><span>Account activation</span></div><section class="panel"><div class="panel-header"><h2>Employee accounts</h2><span class="small muted">${people.length} registered members</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Employee</th><th>Access & department</th><th>Account status</th><th>Administration</th></tr></thead><tbody>${people.map(p=>`<tr><td><strong>${esc(p.name)}</strong><small>${esc(p.employee_id)} · @${esc(p.username)}</small></td><td>${esc(roles[p.role]||human(p.role))}<small>${esc(p.department)}</small></td><td>${badge(p.status)}</td><td><div class="btn-row">${button('Profile','edit-person','small',`data-id="${esc(p.id)}"`)}${p.id!==user.id?button('Reset password','reset-password','small',`data-id="${esc(p.id)}"`):''}${button('Status review','status-request','small',`data-id="${esc(p.id)}"`)}</div></td></tr>`).join('')}</tbody></table></div></section><section class="panel" style="margin-top:24px"><div class="panel-header"><h2>Account status reviews</h2><span class="small muted">Independent founder approval</span></div>${requests.length?requests.map(r=>`<article class="list-card"><div class="list-card-head"><div><h3>${esc(r.name)} → ${esc(human(r.status))}</h3><div class="small muted">Requested by ${esc(r.requested_by_name||nameOf(r.requested_by))} · ${esc(datetime(r.created_at))}</div></div>${badge(r.state)}</div><p class="pre">${esc(r.reason)}</p>${r.review_note?`<p class="small pre">Review: ${esc(r.review_note)}</p>`:''}${isFounder()&&r.state==='pending'&&r.requested_by!==user.id&&r.user_id!==user.id?`<div class="btn-row">${button('Approve status change','status-review','primary small',`data-id="${esc(r.id)}" data-value="approve"`)}${button('Reject','status-review','small',`data-id="${esc(r.id)}" data-value="reject"`)}</div>`:''}</article>`).join(''):empty('No status changes pending','Activation, suspension, leave status, and exits require a documented request and independent founder review.','shield')}</section>`;}
function personFields(p={},create=false){const allowedRoles=isFounder()?Object.entries(roles):[[p.role||'employee',roles[p.role||'employee']||'Team member']];return `<div class="form-grid">${field('Full name','name','text',{required:true,value:p.name,maxlength:100})}${create?field('Username','username','text',{required:true,hint:'Lowercase letters, numbers, dots, underscores or hyphens.',minlength:2,maxlength:60}):field('Designation','designation','text',{required:true,value:p.designation,maxlength:100})}${create?field('Designation','designation','text',{required:true,maxlength:100}):''}${field('Access role','role','select',{value:p.role||'employee',required:true,options:allowedRoles})}${field('Department','department','select',{value:p.department||'Marketing',required:true,options:departments.filter(d=>d!=='Company')})}${field('Reporting manager','manager_id','select',{value:p.manager_id||'',options:[['','No reporting manager'],...peopleOptions(x=>x.id!==p.id&&['founder','hr_lead','team_lead','finance_head'].includes(x.role))]})}${field('Joining date','joined_on','date',{value:p.joined_on||today(),required:true})}${field('Email (private)','email','email',{value:p.email,maxlength:150})}${field('Phone (private)','phone','tel',{value:p.phone,maxlength:40})}</div>`;}
function showTemporaryPassword(password,name){openDialog('Temporary account password',`<p>Share this password privately with <strong>${esc(name)}</strong>. A new personal password is required at the next login.</p><div class="temporary-password" id="temporary-password">${esc(password)}</div><div class="note">${icon('lock')}<span>The password is shown here for this handoff. Resetting a password signs out existing sessions.</span></div><div class="form-actions">${button('Copy password','copy-password')}${button('Done','close-dialog','primary')}</div>`);}
function newPerson(){modalForm('Register a new employee',personFields({},true),b=>api('/api/people','POST',b),{submit:'Create individual account',description:'Complete recruitment and selection first. The employee will receive a unique ID and a temporary password.',after:async r=>{await refresh();showTemporaryPassword(r.temporary_password,r.user?.name||'the employee');}});}
async function editPerson(id){const {user:p,onboarding}=await api('/api/people/'+encodeURIComponent(id));modalForm('Employee profile · '+p.name,personFields(p)+`<div class="note">${icon('shield')}<span>Private contact details are visible only to authorised administrators and this employee. Access changes revoke existing sessions.</span></div>${onboarding?`<p class="hint">Onboarding stage: ${esc(human(onboarding.stage))}. Policy acknowledged: ${esc(onboarding.policy_acknowledged_at?datetime(onboarding.policy_acknowledged_at):'Not yet')}.</p>`:''}`,b=>api('/api/people/'+encodeURIComponent(id),'PATCH',b),{submit:'Update employee profile'});}
function requestStatus(id){const p=person(id);if(!p)return;modalForm('Request status change · '+p.name,field('Proposed account status','status','select',{value:p.status,options:[['active','Active'],['on_leave','On leave'],['suspended','Suspended'],['exited','Exited']]})+field('Reason and supporting context','reason','textarea',{required:true}),b=>api('/api/people/'+encodeURIComponent(id)+'/status-request','POST',b),{submit:'Submit for founder review',description:'A different founder must review this request before the account status changes.'});}
async function reportsPage(){const {summary:s}=await api('/api/reports');records.summary=s;let automation=null,auditEvents=[];if(isFounder()){const [a,b]=await Promise.all([api('/api/automations'),api('/api/audit')]);automation=a;auditEvents=b.events||[];}return pageHeading('Team reports','Understand delivery and coordination without reducing performance to attendance.','','OPERATING RHYTHM')+`<div class="stats">${stat('Active assignments',s.active_tasks,'Scoped to your access','task')}${stat('Overdue',s.overdue_tasks,'Needs a realistic next step','clock')}${stat('Pending reviews',s.pending_reviews,'A response from the reviewer','document')}${stat('Working now',s.working,'Across the organisation','people')}</div><div class="grid-two"><section class="panel"><div class="panel-header"><h2>Department workload</h2></div>${s.department_workload?.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Department</th><th>Active</th><th>Working</th><th>Review</th><th>Overdue</th></tr></thead><tbody>${s.department_workload.map(d=>`<tr><td>${esc(d.department)}</td><td>${d.total}</td><td>${d.working}</td><td>${d.review}</td><td>${d.overdue}</td></tr>`).join('')}</tbody></table></div>`:empty('Workload reports are ready','Departments appear as real assignments are created.','chart')}</section><section class="panel panel-pad"><h2>People & working policy</h2><div class="key-value"><span>Registered active crew</span><strong>${esc(s.people)}</strong></div><div class="key-value"><span>On leave</span><strong>${esc(s.on_leave)}</strong></div><div class="key-value"><span>Pending leave reviews</span><strong>${esc(s.pending_leaves)}</strong></div><div class="key-value"><span>Flexible daily target</span><strong>${esc(s.policy?.daily_target_hours||4)} active hours</strong></div><div class="key-value"><span>Team timezone</span><strong>IST · Asia/Kolkata</strong></div></section></div>${automation?`<section class="panel" style="margin-top:24px"><div class="panel-header"><h2>Workflow automation</h2>${button('Run reminders now','run-automations','small')}</div><div class="panel-body"><div class="note">${icon('refresh')}<span>Reminders run ${esc(automation.schedule?.toLowerCase()||'every 5 minutes')}. Delivery: ${esc(automation.delivery||'In-app notification centre')}. This system keeps a record of each automation run.</span></div>${automation.runs?.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Run</th><th>Recorded</th></tr></thead><tbody>${automation.runs.slice(0,10).map(r=>`<tr><td>${esc(human(r.kind||r.type||r.job_key||r.id||'Scheduled check'))}</td><td>${esc(datetime(r.created_at||r.started_at))}</td></tr>`).join('')}</tbody></table></div>`:empty('No automation runs recorded yet','Scheduled checks create reminders as deadlines and reviews need attention.','refresh')}</section>`:''}${isFounder()?`<section class="panel" style="margin-top:24px"><div class="panel-header"><h2>Audit trail</h2><span class="small muted">Latest ${auditEvents.length} events</span></div>${auditEvents.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Action</th><th>Actor</th><th>Record type</th><th>Time</th></tr></thead><tbody>${auditEvents.map(e=>`<tr><td>${esc(human(e.action))}</td><td>${esc(e.actor_name||'System')}</td><td>${esc(human(e.entity))}</td><td>${esc(datetime(e.created_at))}</td></tr>`).join('')}</tbody></table></div>`:empty('No events yet','Account and workflow changes are recorded automatically.','shield')}</section>`:''}`;}
async function performancePage(){const {reviews=[]}=await api('/api/performance');records.reviews=reviews;return pageHeading('Performance & growth','Recognise quality, delivery, communication, initiative, reliability, and teamwork.',isLead()?plusButton('Record monthly feedback','new-performance'):'','MONTHLY REVIEWS')+`<div class="note" style="margin-bottom:24px">${icon('heart')}<span>Use specific examples and useful next steps. Attendance alone does not determine performance. Review leaders on work distribution, coordination, and response to submitted deliverables.</span></div><section class="panel">${reviews.length?reviews.map(r=>`<article class="list-card"><div class="list-card-head"><div><h3>${esc(r.name||nameOf(r.user_id))} · ${esc(r.period)}</h3><div class="small muted">Reviewer: ${esc(r.reviewer_name||nameOf(r.reviewer_id))}</div></div><span class="badge">${esc(r.department)}</span></div><p class="pre">${esc(r.summary)}</p>${button('Read feedback','performance-details','small',`data-id="${esc(r.id)}"`)}</article>`).join(''):empty('Make feedback a useful habit','Monthly reviews will appear here when an authorised reviewer records feedback.','heart')}</section>`;}
function newPerformance(){modalForm('Record monthly performance feedback',`<div class="form-grid">${field('Team member','user_id','select',{required:true,options:peopleOptions(p=>p.id!==user.id&&(isFounder()||p.manager_id===user.id||p.department===user.department))})}${field('Review month','period','month',{required:true,value:today().slice(0,7),max:today().slice(0,7)})}${['quality','timeliness','communication','initiative','reliability','collaboration'].map(x=>field(human(x),x,'textarea',{required:true,rows:2})).join('')}${field('Overall feedback','summary','textarea',{required:true,wide:true})}${field('Next steps and support','next_steps','textarea',{required:true,wide:true})}</div>`,b=>api('/api/performance','POST',b),{submit:'Save monthly feedback',description:'Write evidence-based qualitative feedback that the employee can act on.'});}
function performanceDialog(id){const r=records.reviews.find(x=>x.id===id);if(!r)return;openDialog('Monthly feedback · '+(r.name||nameOf(r.user_id)),`<p class="small muted">${esc(r.period)} · ${esc(r.reviewer_name||nameOf(r.reviewer_id))}</p>${['quality','timeliness','communication','initiative','reliability','collaboration','summary','next_steps'].map(k=>`<h3>${esc(human(k))}</h3><p class="pre">${esc(r[k])}</p>`).join('')}`);}
async function exitsPage(){const {exits=[]}=await api('/api/exits');records.exits=exits;return pageHeading('Exit & handovers','Document transitions with enough context for responsibilities to continue.',plusButton('Submit an exit request','new-exit'),'TEAM TRANSITIONS')+`<section class="panel">${exits.length?exits.map(x=>`<article class="list-card"><div class="list-card-head"><div><h3>${esc(x.name||nameOf(x.user_id))}</h3><div class="small muted">Proposed last day: ${esc(date(x.proposed_end,true))}</div></div>${badge(x.status)}</div><h3>Handover plan</h3><p class="pre">${esc(x.handover_plan)}</p>${x.review_comment?`<div class="note pre">${esc(x.review_comment)}</div>`:''}${x.status==='pending'&&x.user_id!==user.id&&(isFounder()||user.role==='hr_lead')?`<div class="form-actions">${button('Approve transition','exit-review','primary small',`data-id="${esc(x.id)}" data-value="approve"`)}${button('Reject','exit-review','small',`data-id="${esc(x.id)}" data-value="reject"`)}</div>`:''}</article>`).join(''):empty('No exit requests','Leave a clear handover of projects, access, documents, and pending decisions when transitioning out.','briefcase')}</section>`;}
function newExit(){modalForm('Submit your exit & handover request',field('Proposed last working day','proposed_end','date',{required:true,min:today()})+field('Handover plan','handover_plan','textarea',{required:true,rows:8,hint:'Name responsibility owners, pending deliverables, document locations, and any access that needs transferring.'}),b=>api('/api/exits','POST',b),{submit:'Submit for review',description:'HR and founders review your proposed transition. Account deactivation follows a separate, documented status review.'});}
async function accountPage(){const p=await api('/api/people/'+encodeURIComponent(user.id));records.account=p;return pageHeading('My account','Your identity, access, and account security.','','PERSONAL SETTINGS')+`<div class="account-box stack"><section class="panel panel-pad"><div class="btn-row" style="margin-bottom:20px">${avatar(user)}<div><h2 style="margin-bottom:2px">${esc(user.name)}</h2><div class="small muted">${esc(user.designation||roles[user.role])}</div></div></div>${[['Username',user.username],['Employee ID',user.employee_id],['Role',roles[user.role]||human(user.role)],['Department',user.department],['Reporting manager',user.manager_id?nameOf(user.manager_id):'Leadership'],['Joined',date(user.joined_on,true)],['Account status',human(user.status)],['Email',p.user?.email||'Not provided'],['Phone',p.user?.phone||'Not provided']].map(([k,v])=>`<div class="key-value"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}<div class="form-actions">${button('Change password','change-password','primary')}${button('Sign out','logout')}</div></section><section class="panel panel-pad"><h2>Policy orientation</h2><p class="small muted">Read the company policies, understand your reporting manager, and confirm your responsibilities before starting work.</p><a class="btn" href="#documents">Read team policies</a>${p.onboarding?.policy_acknowledged_at?`<p class="hint">Acknowledged ${esc(datetime(p.onboarding.policy_acknowledged_at))}</p>`:`<div class="form-actions">${button('I have read the team policies','acknowledge-policy','primary')}</div>`}</section></div>`;}
function passwordDialog(locked=false){modalForm(locked?'Choose your personal password':'Change your password',field('Current password','current_password','password',{required:true,autocomplete:'current-password'})+field('New password','new_password','password',{required:true,autocomplete:'new-password',minlength:12,maxlength:128,hint:'Use at least 12 characters. A unique passphrase works well.'})+field('Confirm new password','confirm_password','password',{required:true,autocomplete:'new-password',minlength:12,maxlength:128}),async b=>{if(b.new_password!==b.confirm_password)throw new Error('The new passwords do not match.');if(b.current_password===b.new_password)throw new Error('Choose a password different from your temporary or current password.');return api('/api/auth/password','POST',{current_password:b.current_password,new_password:b.new_password});},{submit:'Set personal password',locked,description:locked?'Your account has a temporary password. Set a new password before opening team records.':'Changing your password protects this individual account.',after:async()=>{toast('Your personal password has been saved.');const r=await api('/api/me');user=r.user;await boot();}});}
function bindPage(){const search=$('#people-search');if(search)search.addEventListener('input',()=>{let count=0;$$('[data-person]').forEach(el=>{el.hidden=!el.dataset.person.includes(search.value.toLowerCase().trim());if(!el.hidden)count++;});$('#people-empty').hidden=count>0;});const form=$('#message-form');if(form)form.addEventListener('submit',async e=>{e.preventDefault();const b=form.querySelector('[type="submit"]');b.disabled=true;try{await api('/api/channels/'+encodeURIComponent(records.currentChannel.id)+'/messages','POST',{body:form.elements.body.value});form.elements.body.value='';await loadChannelMessages(true);}catch(err){formError(form,err.message);}finally{b.disabled=false;}});const feed=$('#message-feed');if(feed)feed.scrollTop=feed.scrollHeight;}
const $$=s=>[...document.querySelectorAll(s)];
async function loadChannelMessages(forceBottom=false){if(!user||!route.startsWith('channel/')||!records.currentChannel)return;const c=records.currentChannel,feed=$('#message-feed');if(!feed)return;const atBottom=feed.scrollHeight-feed.scrollTop-feed.clientHeight<70;const r=await api('/api/channels/'+encodeURIComponent(c.id)+'/messages');if(records.currentChannel?.id!==c.id)return;records.messages=r.messages||[];feed.innerHTML=records.messages.filter(x=>!x.parent_id).map(m=>messageHTML(m,records.messages.filter(x=>x.parent_id===m.id).length)).join('')||empty('Start the conversation','Use this channel for shared context. Submit deliverables on assignments.','people');if(atBottom||forceBottom)feed.scrollTop=feed.scrollHeight;}
function reviewForm(title,path,action,key='note',description=''){modalForm(title,field('Review note',key,'textarea',{required:true,rows:5}),b=>api(path,'PATCH',{action,[key]:b[key]}),{submit:action==='reject'?'Confirm rejection':action==='recommend'?'Recommend to HR':'Confirm approval',description});}
function updateTimers(){const el=$('[data-clock]');if(!el||!records.attendance)return;const total=(records.attendance.attendance||[]).filter(x=>x.user_id===user.id&&x.work_date===today()).reduce((sum,x)=>sum+activeSeconds(x),0);el.innerHTML=esc(clockTime(total))+' <small>/ 4h</small>';const p=$('.clock-progress');if(p)p.value=Math.min(total,14400);const percent=$('[data-clock-percent]');if(percent)percent.textContent=Math.min(100,Math.round(total/144))+'%';}
async function handleLegacyAction(el){const a=el.dataset.action,id=el.dataset.id,value=el.dataset.value;switch(a){case'close-dialog':dialog.close();break;case'toggle-menu':{const sidebar=$('.sidebar'),overlay=$('.mobile-overlay'),open=!sidebar.classList.contains('open');sidebar.classList.toggle('open',open);overlay.classList.toggle('open',open);$('.menu-btn')?.setAttribute('aria-expanded',String(open));break;}case'logout':await api('/api/auth/logout','POST',{});user=null;records={};dialog.close();renderLogin();break;case'refresh':await refresh();break;case'goto-tasks':location.hash='tasks';break;case'new-task':newTask();break;case'task-details':taskDialog(id);break;case'task-filter':taskFilter=value;await navigate();break;case'task-action':await api('/api/tasks/'+encodeURIComponent(id),'PATCH',{action:value});dialog.close();toast('Assignment updated.');await refresh();break;case'task-submit':modalForm('Submit your deliverable',field('Deliverable and context','submission','textarea',{required:true,rows:8,hint:'Include the deliverable URL or the complete text, plus anything your reviewer should check.'}),b=>api('/api/tasks/'+encodeURIComponent(id),'PATCH',{action:'submit',submission:b.submission}),{submit:'Send for review',description:'A formal submission moves this assignment into review.'});break;case'task-revision':modalForm('Request a revision',field('Feedback and required changes','feedback','textarea',{required:true,rows:6}),b=>api('/api/tasks/'+encodeURIComponent(id),'PATCH',{action:'revision',feedback:b.feedback}),{submit:'Request revision'});break;case'clock':await api('/api/attendance','POST',{action:value});toast(value==='clock_in'?'You are clocked in.':value==='pause'?'Your break has started.':value==='resume'?'Your active time has resumed.':'You are clocked out.');await refresh();break;case'new-correction':newCorrection();break;case'correction-review':reviewForm('Review attendance correction','/api/corrections/'+encodeURIComponent(id),value,'review_note','Approved corrections replace the recorded active time for the requested day.');break;case'new-leave':newLeave();break;case'leave-review':reviewForm(value==='recommend'?'Review leave for HR':value==='approve'?'Approve leave':'Reject leave request','/api/leaves/'+encodeURIComponent(id),value,'note',value==='approve'?'Approval updates the shared calendar and notifies the employee.':'Add a clear note for the employee and the next reviewer.');break;case'new-availability':newAvailability();break;case'remove-availability':await api('/api/availability/'+encodeURIComponent(id),'DELETE',{});toast('Availability entry removed.');await refresh();break;case'calendar-prev':calendarOffset--;await navigate();break;case'calendar-next':calendarOffset++;await navigate();break;case'calendar-today':calendarOffset=0;await navigate();break;case'new-meeting':newMeeting();break;case'meeting-details':meetingDialog(id);break;case'meeting-edit':editMeeting(id);break;case'new-document':newDocument();break;case'document-details':{const d=records.documents.find(x=>x.id===id);if(d)openDialog(d.title,`<p class="small muted">${esc(d.department||'Company')} · Version ${esc(d.version||1)}</p><div class="pre">${esc(d.body)}</div><div class="form-actions">${button('Close','close-dialog','primary')}</div>`);break;}case'new-grievance':newGrievance();break;case'grievance-review':{const g=records.grievances.find(x=>x.id===id);modalForm('Review a confidential concern',field('Review state','status','select',{options:[['in_review','In review'],['resolved','Resolved']],value:g?.status})+field('Response to the employee','response','textarea',{required:true,rows:7}),b=>api('/api/grievances/'+encodeURIComponent(id),'PATCH',b),{submit:'Save response'});break;}case'read-notifications':await api('/api/notifications/read','POST',{});await refresh();break;case'read-notification':await api('/api/notifications/read','POST',{id});await refresh();break;case'open-thread':threadDialog(id);break;case'new-person':newPerson();break;case'edit-person':await editPerson(id);break;case'reset-password':modalForm('Reset password · '+nameOf(id),'<div class="note warning">'+icon('lock')+'<span>This signs out the employee’s active sessions and creates a new temporary password. Share it privately with the employee.</span></div>',()=>api('/api/people/'+encodeURIComponent(id)+'/reset-password','POST',{}),{submit:'Reset individual password',after:r=>showTemporaryPassword(r.temporary_password,nameOf(id))});break;case'copy-password':{const v=$('#temporary-password')?.textContent;if(v&&navigator.clipboard){await navigator.clipboard.writeText(v);toast('Password copied. Share it privately.');}else toast('Select the password above and copy it.');break;}case'status-request':requestStatus(id);break;case'status-review':reviewForm('Review account status change','/api/status-requests/'+encodeURIComponent(id),value,'comment','Check the documented reason before changing access or availability.');break;case'run-automations':await api('/api/automations/run','POST',{});toast('Reminder check completed.');await refresh();break;case'new-performance':newPerformance();break;case'performance-details':performanceDialog(id);break;case'new-exit':newExit();break;case'exit-review':reviewForm('Review exit & handover','/api/exits/'+encodeURIComponent(id),value,'comment','Review the handover plan. Account deactivation requires its own status review.');break;case'change-password':passwordDialog();break;case'acknowledge-policy':modalForm('Confirm policy orientation','<p class="small">By confirming, you acknowledge that you have read the team policies and understand your responsibilities, reporting line, and the leave and review workflows.</p>',()=>api('/api/onboarding/acknowledge','POST',{}),{submit:'Confirm acknowledgement'});break;}}

function guideBanner(onboarding={}){return onboarding.guide_completed_at?'':`<section class="welcome-guide"><div class="welcome-copy"><span class="eyebrow">NEW HERE?</span><h2>Follow a simple daily routine.</h2><p>Clock in → open My tasks → submit your work → clock out. The guide explains every step.</p></div><a class="btn primary" href="#guide">Take the quick guide ${icon('arrow')}</a></section>`;}
function ownSchedule(data){return (data.schedules||[]).find(s=>s.user_id===user.id)||null;}
function weekdayLabel(days){const names=['','Mon','Tue','Wed','Thu','Fri','Sat','Sun'];const values=(days||[]).map(Number);return values.join(',')==='1,2,3,4,5'?'Monday–Friday':values.map(x=>names[x]||'').filter(Boolean).join(', ')||'No working days';}
function startLabel(value){if(!/^\d{2}:\d{2}$/.test(value||''))return '—';return time('2026-01-01T'+value+':00+05:30');}
function scheduleSummary(data){
 const row=ownSchedule(data),policy=data.policy||{},state=data.today||row?.today||{},next=data.next_shift||row?.next_shift,labels={upcoming:'Before your start time',due:'Time to clock in',missing:'Clock-in is still missing',on_time:'Clocked in on time',late:'Clocked in late',exempt:'No clock-in required today',not_scheduled:'No scheduled start today'},tone=['missing','late'].includes(state.status)?'amber':['on_time'].includes(state.status)?'green':'';
 const start=state.scheduled_at,showToday=start&&state.status!=='not_scheduled'&&state.status!=='exempt',heading=showToday?'Today’s scheduled start':'Your next clock-in',target=showToday?start:next?.scheduled_at;
 return `<section class="panel schedule-summary panel-pad"><div class="schedule-top"><span class="section-title">${heading}</span><span class="badge ${tone}">${esc(labels[state.status]||'Your clock-in schedule')}</span></div><div class="schedule-time">${target?esc(time(target)):'No start scheduled'}${target?'<small>IST</small>':''}</div><p class="schedule-date">${target?esc(date(target,true))+' · ':''}${esc(weekdayLabel(row?.weekdays||policy.weekdays))}</p>${state.first_clock_in?`<p class="small muted">First clock-in today: <strong>${esc(time(state.first_clock_in))}</strong>${state.status==='late'?` · ${esc(state.minutes_late||0)} minutes after the start`:''}.</p>`:state.status==='exempt'?`<p class="small muted">${esc(human(state.reason||'Approved availability exception'))}. Your exemption is taken into account automatically.</p>`:'<p class="small muted">Signing in opens the app. Use <strong>Clock in</strong> to start recording your work.</p>'}<div class="schedule-rules"><span>${icon('bell')}${esc(policy.reminder_minutes??15)} min before: personal reminder</span><span>${icon('clock')}After ${esc(policy.grace_minutes??10)} min: missed clock-in notice</span><span>${icon('people')}After ${esc(policy.escalation_minutes??30)} min: your lead and HR are notified</span></div><p class="hint">Notifications appear inside TEL OS. Approved leave, exams, unavailability and company holidays are exempt.</p>${row?.pending_change?`<div class="note small">${icon('calendar')}<span>From ${esc(date(row.pending_change.effective_date))}: ${esc(startLabel(row.pending_change.start_time))} IST · ${esc(weekdayLabel(row.pending_change.weekdays))}.</span></div>`:''}</section>`;
}
async function guidePage(){
 const [p,s]=await Promise.all([api('/api/people/'+encodeURIComponent(user.id)),api('/api/schedules')]);records.onboarding=p.onboarding||{};records.schedules=s;const row=ownSchedule(s),policy=s.policy||{},completed=!!records.onboarding.guide_completed_at;
 const steps=[['clock','Clock in at your scheduled time',`Open Attendance and press Clock in when you begin. Your regular start is ${startLabel(row?.start_time||policy.start_time)} IST on ${weekdayLabel(row?.weekdays||policy.weekdays)}. Signing in alone does not record attendance.`,'attendance','Open attendance'],['task','Find your next task','Open My tasks. Select a task to read its expected result, deadline and reviewer. Press Start work when you begin. Ask your lead if anything is unclear.','tasks','Open My tasks'],['document','Submit your finished work','Open the task and select Submit deliverable. Paste the result or a secure file link. Your reviewer will approve it or explain a revision. After approval, mark the task done.','tasks','See my tasks'],['leave','Plan time off before it affects your work','Use Time off to request examination, academic, medical, personal or emergency leave. Your lead reviews it first, then a different HR reviewer verifies it. Approved dates appear in Team calendar.','leave','Request time off'],['clock','Pause for breaks, then clock out','Press Take a break when you stop working and Resume work when you return. Press Clock out at the end of your day. Forgot a step? Request an attendance correction with the actual time.','attendance','Manage attendance'],['people','Keep the team in the loop','Use a team channel for updates and a thread for replies. Read Notifications for reminders and decisions. Policies explain how the team works; private concerns go through the confidential form.','documents','Read the policies']];
 return pageHeading('Start here','A quick guide to your first day in TEL OS.',completed?'<span class="badge green">'+icon('check')+'Guide completed</span>':'','WELCOME TO THE TEAM')+`<section class="guide-intro panel panel-pad"><div class="eyebrow">ONE SIMPLE RHYTHM</div><h2>Clock in. Know your work.<br>Keep everyone in sync.</h2><p>Start on Home for your clock-in time and next steps. The menu on the left opens each part of the workspace; on a phone, use the menu button at the top.</p><div class="guide-route-map"><a href="#home">Home<small>Your daily overview</small></a><a href="#tasks">My tasks<small>Work and reviews</small></a><a href="#attendance">Attendance<small>Your start, breaks and finish</small></a><a href="#notifications">Notifications<small>Reminders and decisions</small></a></div></section><div class="guide-step-list">${steps.map(([glyph,title,body,link,label],i)=>`<section class="guide-step panel"><div class="guide-number">${i+1}</div><div class="guide-step-copy"><div class="guide-step-heading">${icon(glyph)}<h2>${esc(title)}</h2></div><p>${esc(body)}</p><a class="link-btn" href="#${link}">${esc(label)} ${icon('arrow')}</a></div></section>`).join('')}</div><section class="panel panel-pad guide-reminders"><h2>How clock-in reminders work</h2><p>The schedule applies to everyone, including team leads and founders. HR can set a different start time or working days for an individual.</p><div class="reminder-timeline"><div><strong>${esc(policy.reminder_minutes??15)} min before</strong><span>You get a reminder in Notifications.</span></div><div><strong>At your start time</strong><span>Open Attendance and clock in.</span></div><div><strong>${esc(policy.grace_minutes??10)} min after</strong><span>If you have not clocked in, you get a missed-start notice.</span></div><div><strong>${esc(policy.escalation_minutes??30)} min after</strong><span>Your reporting lead and HR are notified if it is still missing.</span></div></div><div class="note">${icon('heart')}<span>Approved leave, company holidays, exams and unavailable periods are taken into account. You can still clock in late; the app records the actual time and never suspends an account automatically.</span></div></section>${isLead()||isHR()?`<section class="panel panel-pad guide-role"><h2>Your ${isHR()?'people administration':'team lead'} tools</h2><p>${isHR()?'Use People admin to register accounts and update verified details. Open Attendance to manage start times, working days and company holidays. Give final leave approval after a different person recommends it.':'Create tasks with clear owners and expected results. Review submitted work promptly, recommend time off, and check the team calendar before assigning work.'}</p><div class="btn-row">${isHR()?'<a class="btn" href="#hr">People admin</a><a class="btn" href="#attendance">Manage schedules</a>':'<a class="btn" href="#tasks">Manage tasks</a><a class="btn" href="#leave">Review time off</a>'}</div></section>`:''}<section class="guide-finish panel panel-pad"><div><h2>${completed?'You can revisit this guide anytime.':'Ready to get started?'}</h2><p>${completed?'Find Start here in the menu whenever you need a refresher.':'Mark the guide complete when you have read it. Policy acknowledgement is a separate step in My account.'}</p></div><div class="btn-row">${completed?'<a class="btn primary" href="#home">Back to Home</a>':button('I understand — finish guide','complete-guide','primary')}<a class="btn" href="#account">My account</a></div></section>`;
}
async function attendancePage(){const s=await api('/api/schedules');records.schedules=s;const html=await legacyAttendancePage();return html.replace('<div class="grid-two">',scheduleSummary(s)+'<div class="grid-two">')+scheduleManagement(s);}
function scheduleManagement(data){
 const rows=data.schedules||[],holidays=data.holidays||[],policy=data.policy||{};if(!isHR())return rows.length>1?`<section class="panel" style="margin-top:24px"><div class="panel-header"><h2>Your team’s start times</h2></div>${scheduleTable(rows,false)}</section>`:'';
 return `<details class="schedule-admin panel" style="margin-top:24px"><summary><span>${icon('settings')}Manage clock-in schedules<small>HR and founder controls</small></span>${icon('chevron')}</summary><div class="panel-body"><div class="schedule-policy"><div><h3>Company default</h3><p>${esc(startLabel(policy.start_time))} IST · ${esc(weekdayLabel(policy.weekdays))}<br><span class="small muted">Effective ${esc(date(policy.effective_date,true))}. New members inherit this schedule.</span>${data.pending_policy?`<br><span class="small accent">Planned from ${esc(date(data.pending_policy.effective_date,true))}: ${esc(startLabel(data.pending_policy.start_time))} IST · ${esc(weekdayLabel(data.pending_policy.weekdays))}.</span>`:''}</p></div>${isFounder()||user.role==='hr_lead'?button('Change company default','schedule-policy','small'):''}</div>${scheduleTable(rows,true)}<section class="holiday-section"><div class="panel-header"><h3>Company holidays</h3>${button('Add holiday','new-holiday','small')}</div>${holidays.length?holidays.map(h=>`<div class="row"><div class="row-main"><strong>${esc(h.title)}</strong><small>${esc(date(h.date,true))} · No scheduled clock-in required</small></div>${button('Remove','remove-holiday','small',`data-id="${esc(h.id)}"`)}</div>`).join(''):'<p class="hint">No company holidays have been added. Add a date to exempt the whole team from clock-in reminders.</p>'}</section></div></details>`;
}
function scheduleTable(rows,editable){return `<div class="table-wrap"><table class="table"><thead><tr><th>Team member</th><th>Start time</th><th>Working days</th><th>Today</th>${editable?'<th>Schedule</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.name)}</strong><small>${esc(r.department)}</small></td><td>${r.enabled?esc(startLabel(r.start_time))+' IST':'Paused'}<small>${r.inherited?'Company default':'Individual schedule'}${r.pending_change?' · Change scheduled':''}</small></td><td>${esc(weekdayLabel(r.weekdays))}</td><td>${badge(r.today?.status||'not_scheduled')}</td>${editable?`<td>${button('Change','schedule-edit','small',`data-id="${esc(r.user_id)}"`)}</td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function scheduleFields(schedule,policy=false){const current=schedule.pending_change||schedule,days=current.weekdays||[1,2,3,4,5];return `<div class="form-grid">${field('Start time (IST)','start_time','time',{required:true,value:current.start_time||'17:00'})}${field('Applies from','effective_date','date',{required:true,value:current.effective_date>=today()?current.effective_date:today(),min:today(),hint:'Choose today only before the start time; otherwise choose a future date.'})}<fieldset class="weekday-field wide"><legend>Working days</legend><div class="weekday-picks">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((name,i)=>`<label><input type="checkbox" name="weekdays" value="${i+1}" ${days.includes(i+1)?'checked':''}><span>${name}</span></label>`).join('')}</div></fieldset><label class="checkline wide"><input name="enabled" type="checkbox" ${current.enabled!==false?'checked':''}>Clock-in reminders enabled</label>${policy?field('Reminder before start (minutes)','reminder_minutes','number',{required:true,value:schedule.reminder_minutes??15,min:0,max:120})+field('Grace period (minutes)','grace_minutes','number',{required:true,value:schedule.grace_minutes??10,min:0,max:60})+field('Notify lead and HR after (minutes)','escalation_minutes','number',{required:true,value:schedule.escalation_minutes??30,min:0,max:240}):''}${policy?'':field('Shared schedule note','note','textarea',{value:current.note||'',wide:true,hint:'Work coordination only; keep medical and personal details out.'})}</div>`;}
function scheduleBody(b,f,policy=false){const weekdays=new FormData(f).getAll('weekdays').map(Number);if(!weekdays.length)throw new Error('Choose at least one working day, or pause this schedule.');const result={start_time:b.start_time,weekdays,enabled:f.elements.enabled.checked,effective_date:b.effective_date,note:b.note||''};if(policy){for(const key of ['reminder_minutes','grace_minutes','escalation_minutes'])result[key]=Number(b[key]);if(result.escalation_minutes<result.grace_minutes)throw new Error('Notify HR and the lead after the grace period has ended.');}return result;}
async function handleAction(el){const a=el.dataset.action,id=el.dataset.id;if(a==='complete-guide'){await api('/api/onboarding/guide','POST',{});toast('Guide complete. You can return here anytime.');await refresh();return;}if(a==='schedule-edit'){const row=records.schedules?.schedules?.find(r=>r.user_id===id);if(!row)throw new Error('Refresh the schedule and try again.');modalForm('Clock-in schedule · '+row.name,scheduleFields(row)+(!row.inherited?'<div class="form-actions">'+button('Use company default','schedule-inherit','',`data-id="${esc(id)}"`)+'</div>':''),(b,f)=>api('/api/schedules/'+encodeURIComponent(id),'PUT',scheduleBody(b,f)),{submit:'Save schedule',description:'This sets this person’s start time and working days. Approved leave, exams and holidays remain exempt.'});return;}if(a==='schedule-inherit'){modalForm('Use the company schedule','<p>This removes the individual override. The current company start time and working days will apply.</p>',()=>api('/api/schedules/'+encodeURIComponent(id),'DELETE',{}),{submit:'Use company default'});return;}if(a==='schedule-policy'){modalForm('Company clock-in schedule',scheduleFields(records.schedules.pending_policy||records.schedules.policy,true),(b,f)=>api('/api/schedules/policy','PATCH',scheduleBody(b,f,true)),{submit:'Save company schedule',description:'Everyone without an individual schedule inherits this. This includes founders and future members.'});return;}if(a==='new-holiday'){modalForm('Add a company holiday',field('Holiday title','title','text',{required:true,maxlength:160})+field('Date','date','date',{required:true,min:today(),value:today()}),b=>api('/api/holidays','POST',b),{submit:'Add holiday',description:'No one receives scheduled clock-in reminders on this date.'});return;}if(a==='remove-holiday'){modalForm('Remove this company holiday?','<p>The team’s usual schedule and clock-in reminders will apply again on this date.</p>',()=>api('/api/holidays/'+encodeURIComponent(id),'DELETE',{}),{submit:'Remove holiday'});return;}return handleLegacyAction(el);}

document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;e.preventDefault();if(el.tagName==='BUTTON')el.disabled=true;try{await handleAction(el);}catch(err){toast(err.message,true);}finally{if(el.isConnected)el.disabled=false;}});
window.addEventListener('hashchange',()=>{navigate().catch(e=>toast(e.message,true));});
window.addEventListener('online',()=>toast('You are back online.'));
window.addEventListener('offline',()=>toast('You are offline. Reconnect before saving changes.',true));
dialog.addEventListener('click',e=>{if(e.target===dialog&&!dialog.classList.contains('no-close')){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
setInterval(updateTimers,1000);
setInterval(()=>{if(user&&!user.must_change_password&&route.startsWith('channel/')&&!dialog.open&&document.visibilityState==='visible')loadChannelMessages().catch(()=>{});},15000);
setInterval(async()=>{if(!user||user.must_change_password||document.visibilityState!=='visible')return;try{const r=await api('/api/notifications');notifications=r.notifications||[];unread=r.unread||0;const b=$('.top-actions a[href="#notifications"]');if(b){b.setAttribute('aria-label','Notification centre'+(unread?', '+unread+' unread':''));const dot=b.querySelector('.dot');if(unread&&!dot){const el=document.createElement('span');el.className='dot';b.append(el);}else if(!unread&&dot)dot.remove();}}catch{}},60000);
const initialiseWorkspace=async()=>{try{const r=await api('/api/me');user=r.user;await boot();}catch(err){renderLogin();}};
if(document.readyState==='complete')initialiseWorkspace();else document.addEventListener('DOMContentLoaded',initialiseWorkspace,{once:true});
